// Tài liệu nghiệp vụ + phân tích chuyên sâu 39 tiêu chí (hiển thị cạnh kết quả, không ảnh hưởng điểm).
const GUIDE = {"R01":{"ten":"CHÊNH LỆCH GIỮA DOANH THU TÍNH THUẾ GTGT VÀ DOANH THU TÍNH THUẾ TNDN","sl1":"Tổng doanh thu HHDV bán ra cả năm trên Tờ khai 01/GTGT (Tổng chỉ tiêu [34] của 12 tháng/4 quý).","sl2":"Doanh thu bán HHDV theo BCTC (Mã số [01] BCKQKD / Chỉ tiêu [04] PL 03-1A theo TT80 hoặc [01] theo TT151) + Các khoản điều chỉnh tăng doanh thu [B2] - Giảm trừ các khoản doanh thu đã tính thuế năm trước [B9] (trên Tờ khai 03/TNDN).","congThuc":"Chênh lệch = SL1 - SL2","dieuKien":"Áp dụng cho mọi doanh nghiệp.","banChat":"Kiểm tra tính đồng nhất về thời điểm ghi nhận doanh thu và lập hóa đơn giữa pháp luật thuế GTGT và thuế TNDN.","hoSo":"Lập Bảng đối chiếu chi tiết chênh lệch giữa TK 511, TK 515, TK 711, TK 3387 với tổng chỉ tiêu [34] trên 01/GTGT. Kiểm tra các hóa đơn xuất giáp ranh kỳ (tháng 12 và tháng 1 năm sau), hợp đồng dịch vụ thu tiền trước và biên bản nghiệm thu.","hieuChinh":["SL2: app cho chọn doanh thu gộp (mã 01) hoặc doanh thu thuần (mã 10) trong Cấu hình. [34] tờ khai đã trừ hóa đơn điều chỉnh giảm, nên khi dùng mã 01 chênh lệch sẽ gồm cả các khoản giảm trừ doanh thu (R13)."],"nhom":{"GTGT":["DT"],"TNDN":["DT"],"Khac":["HĐ"]},"khiDuong":["Trường hợp SL1 > SL2 (Doanh thu kê khai GTGT lớn hơn Doanh thu tính thuế TNDN): (1) Hợp lý khi DN xuất hóa đơn thu tiền trước đối với hoạt động cung cấp dịch vụ (treo trên TK 3387 hoặc Dư Có TK 131, chưa ghi nhận vào TK 511 và chưa điều chỉnh tại [B2]); hoặc có doanh thu tài chính (TK 515), thu nhập thanh lý TSCĐ/phế liệu (TK 711) có kê khai trên tờ khai 01/GTGT nhưng SL2 chỉ lấy doanh thu bán hàng trên BCKQKD. (2) Rủi ro cao khi kế toán hạch toán sót hóa đơn đầu ra trên sổ kế toán (TK 511), làm thiếu doanh thu tính thuế TNDN."],"khiAm":["Trường hợp SL1 < SL2 (Doanh thu kê khai GTGT nhỏ hơn Doanh thu tính thuế TNDN): (1) Hợp lý khi DN có khoản doanh thu không phải kê khai tính nộp thuế GTGT hoặc chênh lệch tỷ giá, hàng bán bị trả lại khác kỳ. (2) Rủi ro nghiêm trọng khi DN đã giao hàng/nghiệm thu dịch vụ và ghi nhận doanh thu TK 511 nhưng chưa xuất hóa đơn GTGT hoặc xuất hóa đơn lùi sang năm sau (vi phạm thời điểm lập hóa đơn)."],"chung":[],"canhBao":{"muc":"Đỏ","dieuKien":null}},"R02":{"ten":"CHÊNH LỆCH THUẾ GTGT ĐẦU RA","sl1":"Tổng chỉ tiêu [35] (Thuế GTGT của HHDV bán ra) trên Tờ khai thuế GTGT mẫu 01/GTGT cả năm.","sl2":"Tổng số phát sinh bên Có TK 33311 (Thuế GTGT đầu ra) trên Bảng cân đối phát sinh tài khoản (BCĐTK).","congThuc":"Chênh lệch = SL1 - SL2","dieuKien":"BCTC theo TT133 hoặc có Bảng cân đối phát sinh tài khoản.","banChat":"Kiểm tra sự khớp đúng giữa số thuế GTGT đầu ra đã kê khai trên hệ thống thuế với số thuế GTGT đầu ra hạch toán trên sổ kế toán.","hoSo":"Đối chiếu Sổ chi tiết TK 33311 theo từng tháng/quý với Bảng kê hóa đơn bán ra và Tờ khai 01/GTGT (kể cả các tờ khai bổ sung KHBS). Tách riêng các bút toán kết chuyển hoặc truy thu sau thanh tra khỏi phát sinh bán ra thuần.","hieuChinh":[],"nhom":{"GTGT":["ĐR"],"Khac":["HĐ"]},"khiDuong":["Trường hợp SL1 > SL2: Kê khai trên tờ khai 01/GTGT lớn hơn sổ kế toán do kế toán bỏ sót chưa hạch toán hóa đơn bán ra vào sổ, hoặc nộp tờ khai bổ sung tăng thuế đầu ra nhưng quên hạch toán bổ sung vào Có TK 33311."],"khiAm":["Trường hợp SL1 < SL2: Đã xuất hóa đơn và ghi sổ Có TK 33311 nhưng bỏ sót không kê khai lên tờ khai 01/GTGT; hoặc có các bút toán điều chỉnh giảm doanh thu/hàng bán trả lại hạch toán Nợ TK 511, 33311 thay vì ghi âm, hoặc hạch toán tiền truy thu thuế năm trước vào Có TK 33311. Nếu bỏ sót kê khai sẽ bị truy thu 100% số lệch và phạt chậm nộp."],"chung":[],"canhBao":{"muc":"Đỏ","dieuKien":null}},"R03":{"ten":"CHÊNH LỆCH THUẾ GTGT ĐẦU VÀO","sl1":"Tổng chỉ tiêu [25] (Tổng số thuế GTGT được khấu trừ kỳ này) trên Tờ khai 01/GTGT cả năm.","sl2":"Tổng số phát sinh bên Nợ TK 133 (Thuế GTGT được khấu trừ - gồm 1331 + 1332) trên BCĐTK.","congThuc":"Chênh lệch = SL1 - SL2","dieuKien":"BCTC theo TT133 hoặc có Bảng cân đối phát sinh tài khoản.","banChat":"Đánh giá tính hợp lệ của số thuế GTGT đầu vào được khấu trừ trên tờ khai so với chứng từ hạch toán thực tế tại sổ kế toán.","hoSo":"Rà soát Sổ chi tiết TK 1331, 1332 đối chiếu từng quý với chỉ tiêu [24] và [25] trên Tờ khai 01/GTGT. Lập danh sách hóa đơn đầu vào nhận sau ngày 31/12 (kéo kỳ kê khai) để giải trình.","hieuChinh":[],"nhom":{"GTGT":["KT"]},"khiDuong":["Trường hợp SL1 > SL2 (Kê khai khấu trừ trên tờ khai lớn hơn phát sinh Nợ TK 133): Rủi ro cực kỳ cao. Dấu hiệu kê khai trùng hóa đơn đầu vào trên tờ khai, kê khai khống số liệu không có chứng từ trên sổ, hoặc hóa đơn của năm trước đã hạch toán Nợ TK 133 năm trước nhưng sang năm nay mới kê khai khấu trừ. Nếu không chứng minh được là hóa đơn chuyển kỳ hợp lệ, CQT sẽ xuất toán ngay phần SL1 > SL2."],"khiAm":["Trường hợp SL1 < SL2 (Kê khai khấu trừ nhỏ hơn phát sinh Nợ TK 133): Do hóa đơn đầu vào về muộn hạch toán vào Nợ TK 133 năm nay nhưng để sang năm sau mới kê khai; hoặc trong Nợ TK 133 có bao gồm phần thuế GTGT không được khấu trừ (cuối kỳ kết chuyển từ Có TK 133 sang Nợ TK 632/642/811)."],"chung":[],"canhBao":{"muc":"Đỏ","dieuKien":null}},"R04":{"ten":"XÁC ĐỊNH THUẾ GTGT ĐẦU VÀO ĐƯỢC KHẤU TRỪ KHI CÓ PHÁT SINH DOANH THU KHÔNG CHỊU THUẾ","sl1":"Tổng chỉ tiêu [24] (Thuế GTGT của HHDV mua vào) trên Tờ khai 01/GTGT cả năm.","sl2":"Tổng chỉ tiêu [25] (Thuế GTGT của HHDV mua vào được khấu trừ) trên Tờ khai 01/GTGT cả năm.","congThuc":"Chênh lệch = SL1 - SL2 (Kiểm tra đồng thời điều kiện Chỉ tiêu [26] > 0)","dieuKien":"Áp dụng khi Doanh nghiệp có phát sinh Doanh thu HHDV bán ra không chịu thuế GTGT (Chỉ tiêu [26] > 0) hoặc doanh thu lãi cho vay.","banChat":"Kiểm tra việc tuân thủ quy định phân bổ thuế GTGT đầu vào dùng chung cho hoạt động chịu thuế và không chịu thuế theo Khoản 2 Điều 14 TT 219/2013/TT-BTC (kỳ trước 01/7/2025) và Luật Thuế GTGT 48/2024, NĐ 181/2025 (từ 01/7/2025).","hoSo":"Tách riêng hóa đơn đầu vào dùng riêng cho hoạt động chịu thuế, không chịu thuế và dùng chung. Thực hiện tính tỷ lệ phân bổ VAT đầu vào dùng chung và điều chỉnh giảm chỉ tiêu [25] (hạch toán phần VAT không được khấu trừ vào chi phí được trừ TK 632/642).","hieuChinh":["Bổ sung căn cứ theo thời kỳ: TT 219/2013 chỉ áp dụng cho kỳ trước 01/7/2025."],"nhom":{"GTGT":["KT"],"TNDN":["CP"]},"khiDuong":[],"khiAm":[],"chung":["Cảnh báo đỏ: Khi doanh nghiệp có phát sinh doanh thu không chịu thuế GTGT (ví dụ: phần mềm, đào tạo, y tế, nông sản sơ chế, lãi cho vay...), nhưng trên Tờ khai 01/GTGT lại kê khai Chỉ tiêu [24] = Chỉ tiêu [25] (tức SL1 - SL2 = 0).","Rủi ro: Doanh nghiệp quên không phân bổ thuế GTGT đầu vào dùng chung (chi phí thuê văn phòng, điện, nước, internet, văn phòng phẩm, dịch vụ kiểm toán, khấu hao TSCĐ dùng chung...) theo tỷ lệ Doanh thu chịu thuế / Tổng doanh thu bán ra. Cơ quan thuế sẽ xuất toán phần thuế GTGT đầu vào tương ứng với tỷ lệ doanh thu không chịu thuế."],"canhBao":{"muc":"Đỏ","dieuKien":"khi [26] > 0 mà [24] = [25]"}},"R05":{"ten":"CHÊNH LỆCH THUẾ GTGT CÒN ĐƯỢC KHẤU TRỪ KỲ TRƯỚC CHUYỂN SANG (ĐẦU NĂM)","sl1":"Chỉ tiêu [22] (Thuế GTGT còn được khấu trừ kỳ trước chuyển sang) trên Tờ khai 01/GTGT kỳ đầu tiên của năm (Tháng 01 hoặc Quý 1).","sl2":"Số dư đầu năm của chỉ tiêu 'Thuế GTGT được khấu trừ' trên Bảng CĐKT (Mã số 152 - TT200; Mã số 181 - TT133 Mẫu B01a; Mã số 151 - TT133 Mẫu B01b) hoặc Dư Nợ đầu năm TK 133.","congThuc":"Chênh lệch = SL1 - SL2","dieuKien":"Áp dụng cho mọi doanh nghiệp.","banChat":"Kiểm tra tính khớp đúng giữa số dư đầu năm của thuế GTGT còn được khấu trừ trên Tờ khai thuế và trên Báo cáo tài chính.","hoSo":"Đối chiếu Chỉ tiêu [43] Tờ khai Tháng 12/Quý 4 năm trước, Chỉ tiêu [22] Tháng 1/Quý 1 năm nay với Số dư Nợ đầu kỳ TK 133. Lập bảng tổng hợp lịch sử các lần kê khai bổ sung (KHBS) để chứng minh nguyên nhân lệch thời điểm.","hieuChinh":[],"nhom":{"GTGT":["KT"]},"khiDuong":[],"khiAm":[],"chung":["Trường hợp SL1 ≠ SL2: Chứng tỏ số liệu cuối năm trước chuyển sang đã bị lệch giữa Tờ khai thuế và Sổ kế toán.","Nguyên nhân phổ biến: (1) Doanh nghiệp nộp tờ khai bổ sung (KHBS) cho các kỳ của năm trước làm thay đổi số thuế khấu trừ nhưng không điều chỉnh vào sổ kế toán hoặc điều chỉnh sai kỳ; (2) Kết chuyển khấu trừ thuế GTGT (Nợ 33311 / Có 1331) năm trước bị sai số học; (3) Có hóa đơn tháng 12 năm trước đã hạch toán Nợ TK 133 năm trước nhưng sang tháng 1 năm nay mới kê khai lên tờ khai."],"canhBao":{"muc":"Đỏ","dieuKien":null}},"R06":{"ten":"CHÊNH LỆCH THUẾ GTGT CÒN ĐƯỢC KHẤU TRỪ CHUYỂN KỲ SAU (CUỐI NĂM)","sl1":"Chỉ tiêu [43] (Thuế GTGT còn được khấu trừ chuyển kỳ sau) trên Tờ khai 01/GTGT kỳ cuối cùng của năm (Tháng 12 hoặc Quý 4).","sl2":"Số dư cuối năm của chỉ tiêu 'Thuế GTGT được khấu trừ' trên Bảng CĐKT (Mã số 152 - TT200; Mã số 181 - TT133 Mẫu B01a; Mã số 151 - TT133 Mẫu B01b) hoặc Dư Nợ cuối năm TK 133.","congThuc":"Chênh lệch = SL1 - SL2","dieuKien":"Áp dụng cho mọi doanh nghiệp.","banChat":"Chốt chặn kiểm tra tổng thể toàn bộ quá trình hạch toán và kê khai khấu trừ thuế GTGT tại thời điểm khóa sổ cuối năm tài chính (31/12).","hoSo":"Kiểm tra toàn bộ 12 bút toán (hoặc 4 bút toán quý) kết chuyển Nợ TK 33311 / Có TK 1331 trong năm. Đảm bảo nguyên tắc: Cuối mỗi kỳ kê khai, không thể vừa còn số thuế được khấu trừ chuyển kỳ sau vừa phát sinh nợ thuế của cùng một sắc thuế GTGT hoạt động SXKD.","hieuChinh":[],"nhom":{"GTGT":["KT"]},"khiDuong":["Trường hợp SL1 > SL2 (Tờ khai còn được khấu trừ nhiều hơn sổ kế toán): Rủi ro cực cao bị cơ quan thuế cắt giảm số thuế được khấu trừ trên tờ khai về bằng số dư sổ sách nếu DN không giải trình được (thường do chưa điều chỉnh giảm trên tờ khai các hóa đơn đã hủy/điều chỉnh giảm trên sổ hoặc quên kết chuyển)."],"khiAm":["Trường hợp SL1 < SL2 (Sổ kế toán dư Nợ TK 133 lớn hơn Chỉ tiêu [43]): Do kế toán quên thực hiện bút toán kết chuyển khấu trừ thuế GTGT cuối tháng/quý (Nợ TK 33311 / Có TK 1331), khiến cả TK 1331 và TK 33311 đều treo số dư ảo lớn trên BCTC; hoặc có hóa đơn đầu vào treo trên TK 133 chờ kê khai vào năm sau."],"chung":[],"canhBao":{"muc":"Đỏ","dieuKien":null}},"R07":{"ten":"CHÊNH LỆCH GIÁ TRỊ HHDV BÁN RA, THUẾ ĐẦU RA VÀ PHÁT SINH CÔNG NỢ PHẢI THU KHÁCH HÀNG","sl1":"Tổng Doanh thu GTGT [34] (hoặc Doanh thu TNDN) + Thuế GTGT đầu ra [35] trên Tờ khai 01/GTGT cả năm.","sl2":"Tổng số phát sinh bên Nợ TK 131 (Phải thu của khách hàng) trên BCĐTK.","congThuc":"Chênh lệch = SL1 - SL2","dieuKien":"BCTC theo TT133 hoặc có Bảng cân đối phát sinh tài khoản.","banChat":"Đánh giá mối tương quan giữa tổng giá trị thanh toán trên hóa đơn đầu ra với tổng số phát sinh phải thu khách hàng trong kỳ.","hoSo":"Khuyến nghị chuẩn hóa quy trình: Mọi nghiệp vụ bán hàng đều hạch toán qua TK 131. Khi giải trình chỉ tiêu R07, bóc tách trên Sổ cái TK 131 các bút toán Nợ TK 131 không đối ứng với Có TK 511/711/33311.","hieuChinh":[],"nhom":{"GTGT":["DT"],"TNDN":["DT"],"Khac":["HĐ"]},"khiDuong":["Trường hợp SL1 > SL2: Doanh nghiệp có các nghiệp vụ bán hàng thu tiền ngay bằng tiền mặt hoặc chuyển khoản (hạch toán thẳng Nợ TK 111, 112 / Có TK 511, 3331 mà không đi qua TK 131). Rủi ro cần kiểm tra: Các hóa đơn bán ra thu tiền mặt có làm âm quỹ hoặc vi phạm quy định thanh toán không?"],"khiAm":["Trường hợp SL1 < SL2 (Phát sinh Nợ TK 131 lớn hơn Tổng Doanh thu + VAT đầu ra): (1) Hợp lý khi có bút toán chuyển trả lại tiền khách hàng ứng trước (Nợ TK 131 / Có TK 112), đánh giá chênh lệch tỷ giá cuối kỳ, thu hộ/chi hộ hoặc cấn trừ công nợ. (2) Rủi ro cao khi DN ghi nhận công nợ phải thu khách hàng đối ứng với các tài khoản trung gian (TK 3388, 1388) để giấu doanh thu, không đưa qua TK 511 và không kê khai thuế."],"chung":[],"canhBao":{"muc":"Đỏ","dieuKien":"khi SL1 < SL2","ghiChu":"SL1 > SL2 (bán thu tiền ngay) xếp Vàng"}},"R08":{"ten":"CHÊNH LỆCH GIÁ TRỊ HHDV MUA VÀO, THUẾ ĐẦU VÀO VÀ PHÁT SINH CÔNG NỢ PHẢI TRẢ NCC","sl1":"Tổng Giá trị HHDV mua vào [23] + Thuế GTGT mua vào [24] trên Tờ khai 01/GTGT cả năm.","sl2":"Tổng số phát sinh bên Có TK 331 (Phải trả cho người bán) trên BCĐTK.","congThuc":"Chênh lệch = SL1 - SL2","dieuKien":"BCTC theo TT133 hoặc có Bảng cân đối phát sinh tài khoản.","banChat":"Kiểm tra tính logic giữa tổng giá trị mua vào kê khai thuế GTGT với tổng công nợ phải trả nhà cung cấp và điều kiện thanh toán không dùng tiền mặt.","hoSo":"Lọc toàn bộ các bút toán Nợ TK 133 đối ứng trực tiếp với Có TK 111, 141 có tổng thanh toán từ ngưỡng thanh toán không dùng tiền mặt (05 triệu đồng từ 01/7/2025; 20 triệu đồng trước đó), kể cả cộng dồn theo MST nhà cung cấp trong cùng ngày để cảnh báo trên App.","hieuChinh":["Cập nhật ngưỡng thanh toán không dùng tiền mặt: tài liệu gốc ghi 20 triệu đồng; từ 01/7/2025 (GTGT) và 15/12/2025 (TNDN) là 05 triệu đồng."],"nhom":{"GTGT":["KT"],"TNDN":["CP"]},"khiDuong":["Trường hợp SL1 > SL2 (Tổng mua vào trên tờ khai lớn hơn phát sinh Có TK 331): Doanh nghiệp mua hàng hóa, dịch vụ thanh toán trực tiếp bằng tiền mặt, tiền gửi ngân hàng hoặc tạm ứng (Nợ TK 152, 156, 642, 133 / Có TK 111, 112, 141) không qua TK 331. Rủi ro trọng yếu: Các hóa đơn mua vào từ ngưỡng thanh toán không dùng tiền mặt trở lên (20 triệu đồng đến 30/6/2025; 05 triệu đồng, giá đã có thuế, từ 01/7/2025 theo Luật GTGT 48/2024 và NĐ 181/2025), kể cả nhiều hóa đơn của cùng 1 nhà cung cấp trong cùng 1 ngày có tổng từ ngưỡng đó, mà thanh toán bằng tiền mặt (Có TK 111/141) thì bị loại thuế GTGT đầu vào; chi phí bị loại khi tính TNDN nếu trả tiền mặt từ ngưỡng của Luật TNDN (20 triệu đồng; 05 triệu đồng từ 15/12/2025 theo NĐ 320/2025 – cần đối chiếu)."],"khiAm":["Trường hợp SL1 < SL2 (Phát sinh Có TK 331 lớn hơn tổng mua vào kê khai thuế): Do mua HHDV bằng hóa đơn bán hàng thông thường (không kê khai trên 01/GTGT), chi phí nhập khẩu, hoặc nhà cung cấp hoàn trả tiền ứng trước (Nợ TK 112 / Có TK 331). Cần rà soát các khoản ghi Có TK 331 nhưng không có hóa đơn hợp pháp."],"chung":[],"canhBao":{"muc":"Đỏ","dieuKien":null}},"R09":{"ten":"CHÊNH LỆCH HẠCH TOÁN THUẾ GTGT ĐẦU VÀO ĐƯỢC HOÀN","sl1":"Phát sinh bên Có TK 133 (Thuế GTGT được khấu trừ) - Phát sinh bên Nợ TK 33311 (Thuế GTGT đầu ra phải nộp / đã khấu trừ trong kỳ) trên BCĐTK.","sl2":"Số thuế GTGT đã được hoàn trong kỳ theo quyết định hoàn thuế (đúng như mẫu CQT). Chỉ tiêu [42] (số đề nghị hoàn) chỉ dùng tham khảo, vì số được hoàn và kỳ nhận tiền có thể khác số đề nghị.","congThuc":"Chênh lệch = SL1 - SL2","dieuKien":"BCTC theo TT133 hoặc có Bảng cân đối phát sinh tài khoản.","banChat":"Kiểm tra các khoản ghi giảm thuế GTGT đầu vào (Bên Có TK 133) ngoài bút toán khấu trừ với thuế đầu ra và hoàn thuế.","hoSo":"Bóc tách chi tiết các tài khoản đối ứng với bên Có TK 133 (ngoài TK 33311) để kiểm tra tính hợp lệ khi tính vào chi phí TNDN hoặc điều chỉnh vào chỉ tiêu [B4].","hieuChinh":["SL2: mẫu CQT dùng 'thuế GTGT đã được hoàn trong kỳ'. Tài liệu gốc lấy [42] (số đề nghị hoàn) – có thể lệch khi hoàn một phần hoặc nhận tiền ở kỳ sau. App dùng số theo quyết định hoàn."],"nhom":{"GTGT":["KT","HT"],"TNDN":["CP"]},"khiDuong":[],"khiAm":[],"chung":["Về mặt kế toán: Tổng phát sinh Có TK 133 = Số thuế kết chuyển khấu trừ (Nợ TK 33311) + Số thuế đề nghị hoàn (Chỉ tiêu [42]) + Số thuế GTGT đầu vào không được khấu trừ kết chuyển vào chi phí/nguyên giá (Nợ TK 632, 642, 811, 211 / Có TK 133) + Hóa đơn mua vào trả lại/điều chỉnh giảm.","Rủi ro: Khi SL1 - SL2 ≠ 0, cơ quan thuế sẽ xoáy sâu vào phần chênh lệch này để kiểm tra: (1) Nếu là thuế GTGT đề nghị hoàn thì đã dừng khấu trừ đúng kỳ chưa; (2) Nếu là thuế GTGT không được khấu trừ hạch toán vào chi phí (TK 642, 811) thì khoản chi phí đó có được trừ khi tính thuế TNDN không (nếu do hóa đơn bất hợp pháp, không phục vụ SXKD hoặc trả tiền mặt từ ngưỡng thanh toán không dùng tiền mặt thì phần VAT này cũng không được tính vào chi phí được trừ TNDN)."],"canhBao":{"muc":"Đỏ","dieuKien":null}},"R10":{"ten":"CHÊNH LỆCH DÒNG TIỀN THU TỪ BÁN HÀNG, CUNG CẤP DỊCH VỤ VÀ DOANH THU KHÁC","sl1":"Tổng Doanh thu & Thuế GTGT bán ra (Chỉ tiêu [34] + [35] trên 01/GTGT) + Biến động số dư Phải thu ngắn hạn của khách hàng Mã 131 (Đầu kỳ - Cuối kỳ) - Biến động số dư Người mua trả tiền trước ngắn hạn Mã 312/412 (Đầu kỳ - Cuối kỳ) trên Bảng CĐKT.","sl2":"Chỉ tiêu 'Tiền thu từ bán hàng, cung cấp dịch vụ và doanh thu khác' (Mã số [01] trên Báo cáo Lưu chuyển tiền tệ).","congThuc":"Chênh lệch = SL1 - SL2","dieuKien":"Doanh nghiệp lập Báo cáo Lưu chuyển tiền tệ theo phương pháp trực tiếp.","banChat":"Phục dựng dòng tiền thu từ khách hàng dựa trên công thức cân đối công nợ và doanh thu kê khai thuế để so sánh với dòng tiền thu thực tế trên Báo cáo LCTT.","hoSo":"Kiểm tra công thức lập Mã số [01] trên Báo cáo LCTT và đối chiếu với Sổ quỹ TK 111, Sổ phụ ngân hàng TK 112. Giải trình rõ các bút toán cấn trừ công nợ không phát sinh dòng tiền (Non-cash transactions).","hieuChinh":[],"nhom":{"GTGT":["DT"],"TNDN":["DT"],"Khac":["HĐ","KH"]},"khiDuong":["Trường hợp SL1 > SL2: Doanh nghiệp có các nghiệp vụ bán hàng thu tiền nhưng cấn trừ công nợ (Nợ TK 331 / Có TK 131), thu hồi nợ dài hạn, xóa nợ khó đòi, hoặc lập Báo cáo LCTT phân loại nhầm dòng tiền thu bán hàng sang Mã số [06] (Tiền thu khác)."],"khiAm":["Trường hợp SL1 < SL2 (Tiền thực thu tại Mã số [01] LCTT lớn hơn dòng tiền thu tính từ doanh thu đã kê khai): Đây là cảnh báo rủi ro cực lớn. Dấu hiệu doanh nghiệp có phát sinh dòng tiền thu từ bán hàng/cung cấp dịch vụ qua quỹ tiền mặt/ngân hàng nhưng chưa xuất hóa đơn, chưa kê khai doanh thu tính thuế GTGT và TNDN (hoặc hạch toán treo vào TK 3388, 341 nhưng phần mềm vẫn nhặt vào Mã [01] LCTT)."],"chung":[],"canhBao":{"muc":"Đỏ","dieuKien":"khi SL1 < SL2"}},"R11":{"ten":"CHÊNH LỆCH DÒNG TIỀN CHI TRẢ CHO NGƯỜI CUNG CẤP HHDV","sl1":"Tổng Giá trị & Thuế GTGT HHDV mua vào (Chỉ tiêu [23] + [24] trên 01/GTGT) + Biến động số dư Phải trả người bán ngắn hạn Mã 311/411 (Đầu kỳ - Cuối kỳ) - Biến động số dư Trả trước cho người bán ngắn hạn Mã 132 (Đầu kỳ - Cuối kỳ) trên Bảng CĐKT.","sl2":"Giá trị tuyệt đối của Chỉ tiêu 'Tiền chi trả cho người cung cấp hàng hóa, dịch vụ' (Mã số [02] trên Báo cáo Lưu chuyển tiền tệ).","congThuc":"Chênh lệch = SL1 - SL2","dieuKien":"Doanh nghiệp lập Báo cáo Lưu chuyển tiền tệ theo phương pháp trực tiếp.","banChat":"Kiểm tra tính xác thực của dòng tiền thanh toán cho nhà cung cấp so với khối lượng hóa đơn đầu vào đã kê khai khấu trừ thuế.","hoSo":"Bóc tách các khoản mua vào không kê khai trên tờ khai 01/GTGT, các khoản mua sắm TSCĐ (nằm ở Mã [21] LCTT nhưng công nợ hạch toán chung trên TK 331) và các biên bản bù trừ công nợ hợp pháp.","hieuChinh":[],"nhom":{"GTGT":["KT"],"TNDN":["CP"],"Khac":["KH"]},"khiDuong":["Trường hợp SL1 > SL2 (Tổng mua vào kê khai thuế + giảm nợ phải trả lớn hơn nhiều so với tiền thực chi trên LCTT): Dấu hiệu doanh nghiệp kê khai hóa đơn đầu vào lớn nhưng không có dòng tiền thanh toán thực tế tương ứng, hoặc giải ngân qua các bút toán cấn trừ công nợ 3 bên/thanh toán tiền mặt khống để giảm số dư TK 331 (dấu hiệu rủi ro về mua bán hóa đơn hoặc thanh toán không qua ngân hàng)."],"khiAm":["Trường hợp SL1 < SL2 (Tiền chi trên LCTT lớn hơn tổng mua vào trên tờ khai 01/GTGT): Hợp lý khi doanh nghiệp chi trả cho các hàng hóa, dịch vụ không có hóa đơn GTGT (hóa đơn bán hàng trực tiếp, dịch vụ ngân hàng, mua hàng theo bảng kê 01/TNDN...) không kê khai trên 01/GTGT."],"chung":[],"canhBao":{"muc":"Đỏ","dieuKien":null}},"R12":{"ten":"CHÊNH LỆCH GIÁ VỐN VÀ THÀNH PHẨM, HÀNG HÓA XUẤT KHO","sl1":"Tổng số phát sinh bên Có TK 154 (Chi phí SXKD dở dang) + Có TK 155 (Thành phẩm) + Có TK 156 (Hàng hóa) trên BCĐTK.","sl2":"Tổng số phát sinh bên Nợ TK 632 (Giá vốn hàng bán) trên BCĐTK.","congThuc":"Chênh lệch = SL1 - SL2","dieuKien":"BCTC theo TT133 hoặc có Bảng cân đối phát sinh tài khoản.","banChat":"Kiểm tra sự tương ứng giữa giá trị hàng hóa, thành phẩm xuất ra khỏi kho với giá vốn hàng bán ghi nhận trong kỳ.","hoSo":"Trên App Check Rủi Ro, cần thiết lập bộ lọc kiểm tra: Nếu DN sản xuất có bút toán Nợ 155 / Có 154 thì phải loại trừ phần trùng này khi tính SL1. Đồng thời liệt kê chi tiết toàn bộ các tài khoản đối ứng với Nợ TK 632 và Có TK 155, 156.","hieuChinh":["Bút toán 154 → 155 (nhập kho thành phẩm) gây cộng trùng SL1 ở cả TT133 và TT200, không riêng TT133.","Theo TT200, chi phí 621, 622, 627 kết chuyển vào 154 rồi mới sang 155/632; chỉ phần chi phí chung cố định không phân bổ và phần vượt định mức mới ghi thẳng 632."],"nhom":{"GTGT":["DT"],"TNDN":["DT","CP"],"Khac":["HĐ","KH"]},"khiDuong":["Trường hợp SL1 > SL2 (Tổng xuất kho 154, 155, 156 lớn hơn Nợ TK 632): (1) Hợp lý đối với DN sản xuất (cả TT133 và TT200) khi kết chuyển giá thành từ Có TK 154 sang nhập kho Nợ TK 155 (làm tổng SL1 bị cộng lặp cả bước nhập kho TP và bước xuất bán TP), hoặc xuất kho gửi bán (Nợ TK 157), luân chuyển kho nội bộ. (2) Rủi ro thuế rất cao khi DN xuất kho hàng hóa, thành phẩm để tiêu dùng nội bộ, biếu tặng khách hàng/nhân viên, khuyến mại (hạch toán Nợ TK 641, 642, 353 / Có TK 155, 156) nhưng KHÔNG lập hóa đơn và KHÔNG kê khai thuế GTGT đầu ra; hoặc đã xuất kho giao hàng cho khách nhưng treo trên TK 1388 chưa ghi nhận doanh thu và giá vốn."],"khiAm":["Trường hợp SL1 < SL2 (Giá vốn Nợ TK 632 lớn hơn Tổng xuất kho): (1) Hợp lý khi có chi phí ghi thẳng vào giá vốn không qua kho: chi phí sản xuất chung cố định không phân bổ, chi phí nguyên vật liệu/nhân công vượt mức bình thường (Nợ TK 632 / Có TK 621, 622, 627 theo TT200), hoặc mua hàng bán thẳng tay ba không qua kho (Nợ TK 632 / Có TK 331), hoặc trích lập dự phòng giảm giá HTK (Nợ 632 / Có 2294). (2) Rủi ro cao khi kế toán hạch toán khống bút toán Nợ TK 632 / Có TK 331, 335, 1388... để đẩy cao giá vốn nhằm trốn thuế TNDN."],"chung":[],"canhBao":{"muc":"Đỏ","dieuKien":null}},"R13":{"ten":"CÁC KHOẢN GIẢM TRỪ DOANH THU","sl1":"Chỉ tiêu [06] trên Phụ lục 03-1A (theo TT80/2021/TT-BTC) hoặc Chỉ tiêu [03] (theo TT151/2014/TT-BTC) / Mã số [02] trên BCKQKD.","sl2":"Không áp dụng (Đánh giá trực tiếp khi số liệu phát sinh > 0).","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Báo cáo kết quả hoạt động kinh doanh.","banChat":"Rà soát tính hợp pháp của các khoản Chiết khấu thương mại, Giảm giá hàng bán, Hàng bán bị trả lại (TK 521 theo TT200; TT133 ghi giảm trực tiếp TK 511) làm giảm trực tiếp doanh thu tính thuế.","hoSo":"Chuẩn bị bộ hồ sơ cho từng khoản giảm trừ trên TK 521 (TT133: TK 511): Hợp đồng/Chính sách chiết khấu, Bảng tính đạt doanh số, Biên bản trả hàng, Hóa đơn điều chỉnh/trả hàng và Phiếu nhập kho.","hieuChinh":["Bỏ nội dung 'khấu trừ thuế TNCN khi chi chiết khấu thanh toán cho cá nhân' vì chưa xác minh được căn cứ."],"nhom":{"GTGT":["DT","ĐR"],"TNDN":["DT","PN","UĐ"],"Khac":["HĐ","KH"]},"khiDuong":[],"khiAm":[],"chung":["Khi chỉ tiêu này > 0, cơ quan thuế tập trung kiểm tra 3 rủi ro cốt lõi: (1) Chiết khấu thương mại có được quy định rõ trong hợp đồng kinh tế hoặc chính sách bán hàng công bố trước đó không? Có bị nhầm lẫn với Chiết khấu thanh toán (phải hạch toán vào TK 635, không được ghi giảm trừ doanh thu) không?","(2) Hàng bán bị trả lại: Có đầy đủ Biên bản trả lại hàng có chữ ký hai bên, Hóa đơn điện tử xử lý hàng trả lại đúng quy định tại NĐ 123/2020/NĐ-CP & NĐ 70/2025/NĐ-CP, và Phiếu nhập kho lại hàng trả về (kèm bút toán giảm giá vốn Nợ TK 155, 156 / Có TK 632) hay không? Rất nhiều DN chỉ ghi giảm doanh thu mà quên không ghi giảm giá vốn hàng bán tương ứng.","(3) Giảm trừ doanh thu sai kỳ tính thuế đối với các hóa đơn điều chỉnh/trả hàng phát sinh sau ngày 31/12."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R14":{"ten":"CHỈ TIÊU THU NHẬP KHÁC","sl1":"Chỉ tiêu [19] trên Phụ lục 03-1A (theo TT80/2021/TT-BTC) hoặc Chỉ tiêu [16] (theo TT151/2014/TT-BTC) / Mã số [31] trên BCKQKD (Phát sinh Có TK 711).","sl2":"Không áp dụng (Đánh giá trực tiếp khi số liệu phát sinh > 0).","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Báo cáo kết quả hoạt động kinh doanh.","banChat":"Kiểm tra nghĩa vụ lập hóa đơn, kê khai thuế GTGT đầu ra và điều kiện hưởng ưu đãi thuế TNDN đối với các khoản Thu nhập khác (TK 711).","hoSo":"In Sổ chi tiết TK 711, phân loại từng nghiệp vụ: Nghiệp vụ nào thuộc diện không phải kê khai tính nộp thuế GTGT (như thu tiền bồi thường bằng tiền, tiền phạt vi phạm hợp đồng) và nghiệp vụ nào bắt buộc phải xuất hóa đơn GTGT.","hieuChinh":["Thuế suất: từ kỳ tính thuế 2025 áp dụng 15%/17%/20% theo quy mô doanh thu (Luật TNDN 67/2025)."],"nhom":{"GTGT":["DT"],"TNDN":["MG"],"Khac":["HĐ","KH"]},"khiDuong":[],"khiAm":[],"chung":["Rủi ro 1 (Về Hóa đơn & Thuế GTGT): Các khoản thu nhập khác từ thanh lý, nhượng bán TSCĐ, bán phế liệu, vật tư thu hồi, hàng khuyến mại không kèm điều kiện mua hàng, tiền bồi thường bằng hàng hóa/dịch vụ... bắt buộc phải lập hóa đơn GTGT và kê khai nộp thuế GTGT đầu ra (10% hoặc 8%). Nhiều kế toán chỉ hạch toán Nợ TK 111, 112, 131 / Có TK 711 mà không xuất hóa đơn GTGT.","Rủi ro 2 (Về Ưu đãi thuế TNDN - MG): Nếu doanh nghiệp đang hưởng ưu đãi thuế TNDN, các khoản thu nhập khác không liên quan trực tiếp đến lĩnh vực/địa bàn ưu đãi (như xóa nợ không xác định được chủ, thu phạt hợp đồng không gắn với HĐKD ưu đãi, thanh lý tài sản không phục vụ SXKD ưu đãi...) không được áp dụng thuế suất ưu đãi hay miễn giảm mà phải tính thuế TNDN theo thuế suất phổ thông (20%; từ kỳ tính thuế 2025 là 15%/17%/20% theo quy mô doanh thu – Luật TNDN 67/2025)."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R15":{"ten":"CÁC KHOẢN ĐIỀU CHỈNH TĂNG DOANH THU","sl1":"Chỉ tiêu [B2] trên Tờ khai quyết toán thuế TNDN mẫu 03/TNDN.","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Tờ khai quyết toán thuế TNDN 03/TNDN.","banChat":"Đánh giá các khoản chênh lệch thời điểm ghi nhận doanh thu giữa Chuẩn mực kế toán và Luật thuế TNDN làm tăng doanh thu tính thuế trong kỳ.","hoSo":"Lưu trữ bảng thuyết minh chi tiết chỉ tiêu [B2] để làm căn cứ giảm trừ tại chỉ tiêu [B9] ở các năm tiếp theo khi ghi nhận doanh thu trên BCTC, tránh bị đánh thuế TNDN 2 lần trên cùng một khoản doanh thu.","hieuChinh":[],"nhom":{"GTGT":["DT"],"TNDN":["DT"],"Khac":["KH"]},"khiDuong":[],"khiAm":[],"chung":["Khi [B2] > 0: Cơ quan thuế kiểm tra xem khoản doanh thu điều chỉnh tăng này đã được lập hóa đơn và kê khai đầy đủ trên Tờ khai 01/GTGT trong năm chưa; đồng thời giá vốn tương ứng với khoản doanh thu tăng này đã được điều chỉnh hợp lý chưa.","Khi [B2] = 0 nhưng doanh nghiệp có phát sinh xuất hóa đơn thu tiền trước hoặc doanh thu chưa thực hiện (R27, R30): Rủi ro doanh nghiệp chưa thực hiện điều chỉnh tăng doanh thu tính thuế TNDN theo quy định."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R16":{"ten":"GIẢM TRỪ CÁC KHOẢN DOANH THU ĐÃ TÍNH THUẾ NĂM TRƯỚC","sl1":"Chỉ tiêu [B9] trên Tờ khai quyết toán thuế TNDN mẫu 03/TNDN.","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Tờ khai quyết toán thuế TNDN 03/TNDN.","banChat":"Kiểm tra tính có thật và hợp pháp của việc điều chỉnh giảm doanh thu chịu thuế TNDN năm nay đối với các khoản đã tính thuế ở các năm trước.","hoSo":"Đính kèm Tờ khai 03/TNDN năm trước (có số liệu tại [B2]) hoặc Quyết định xử lý về thuế của đoàn thanh tra năm trước (đã kéo doanh thu về năm trước) để chứng minh khoản doanh thu hạch toán trên TK 511 năm nay đã hoàn thành nghĩa vụ thuế.","hieuChinh":["Thay '20%' bằng 'thuế suất áp dụng' (15%/17%/20% từ kỳ 2025)."],"nhom":{"GTGT":["DT"],"TNDN":["DT"],"Khac":["KH"]},"khiDuong":[],"khiAm":[],"chung":["Khi [B9] > 0, doanh nghiệp đang làm giảm trực tiếp thu nhập chịu thuế TNDN năm hiện tại.","Rủi ro trọng yếu: Cơ quan thuế sẽ đối chiếu ngược lại Tờ khai 03/TNDN của các năm trước xem tại chỉ tiêu [B2] (hoặc Biên bản thanh tra thuế các năm trước) khoản doanh thu này đã thực sự được kê khai và nộp thuế TNDN hay chưa. Nếu năm trước chưa từng đưa vào [B2] hoặc chưa bị truy thu thuế TNDN qua thanh tra, toàn bộ giá trị kê khai tại [B9] sẽ bị xuất toán và truy thu thuế TNDN theo thuế suất áp dụng."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R17":{"ten":"CÁC KHOẢN CHI KHÔNG ĐƯỢC TRỪ KHI XÁC ĐỊNH THU NHẬP CHỊU THUẾ","sl1":"Chỉ tiêu [B4] trên Tờ khai quyết toán thuế TNDN mẫu 03/TNDN.","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Tờ khai quyết toán thuế TNDN 03/TNDN.","banChat":"Kiểm tra tính đầy đủ của các khoản chi phí bị loại theo Điều 4 TT 96/2015/TT-BTC (từ kỳ tính thuế 2025: Luật TNDN 67/2025, NĐ 320/2025) và đối chiếu chéo với thuế GTGT đầu vào không được khấu trừ.","hoSo":"Trên App Check Rủi Ro, thiết lập bảng kê chi tiết cấu thành chỉ tiêu [B4] và tự động nhắc người dùng kiểm tra phần thuế GTGT đầu vào tương ứng của từng khoản chi phí bị loại tại [B4].","hieuChinh":["Cập nhật ngưỡng tiền mặt (05 triệu đồng từ 2025) và căn cứ: TT 96/2015 cho kỳ trước 2025; Luật TNDN 67/2025, NĐ 320/2025 từ kỳ 2025 (mức khống chế lãi vay 150% lãi suất cơ bản – cần đối chiếu văn bản mới)."],"nhom":{"GTGT":["KT"],"TNDN":["CP"]},"khiDuong":[],"khiAm":[],"chung":["Rủi ro 1 (Đối chiếu chéo sang Thuế GTGT - KT): Khi doanh nghiệp tự giác loại một khoản chi phí tại chỉ tiêu [B4] (do không phục vụ SXKD, hóa đơn không hợp pháp, hóa đơn từ ngưỡng thanh toán không dùng tiền mặt mà trả tiền mặt, khấu hao xe ô tô dưới 9 chỗ phần vượt 1,6 tỷ đồng...), phần thuế GTGT đầu vào tương ứng của các hóa đơn đó CŨNG KHÔNG ĐƯỢC KHẤU TRỪ. Cơ quan thuế sẽ kiểm tra xem DN đã loại phần VAT đầu vào tương ứng khỏi Tờ khai 01/GTGT hay chưa.","Rủi ro 2 (Kê khai thiếu tại [B4]): Nếu trên BCTC có Chi phí khác (TK 811 - tiền phạt hành chính, chậm nộp thuế), Chi phí lãi vay khi chưa góp đủ vốn điều lệ (TK 635), hoặc lãi vay vượt mức khống chế (150% lãi suất cơ bản đối với cá nhân / 30% EBITDA đối với giao dịch liên kết theo NĐ 132/2020/NĐ-CP) nhưng [B4] = 0 hoặc quá nhỏ."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R18":{"ten":"CÁC KHOẢN ĐIỀU CHỈNH LÀM TĂNG LỢI NHUẬN TRƯỚC THUẾ KHÁC","sl1":"Chỉ tiêu [B7] trên Tờ khai quyết toán thuế TNDN mẫu 03/TNDN.","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Tờ khai quyết toán thuế TNDN 03/TNDN.","banChat":"Rà soát các khoản điều chỉnh tăng lợi nhuận trước thuế khác (ngoài doanh thu và chi phí không được trừ) và ảnh hưởng đến ưu đãi thuế.","hoSo":"Lập bảng thuyết minh chi tiết các khoản điều chỉnh tại [B7], đặc biệt là bảng đánh giá lại số dư ngoại tệ cuối năm của các tài khoản 1112, 1122, 131.","hieuChinh":[],"nhom":{"GTGT":["DT"],"TNDN":["MG"]},"khiDuong":[],"khiAm":[],"chung":["Chỉ tiêu [B7] thường bao gồm: Lỗ chênh lệch tỷ giá do đánh giá lại các khoản mục tiền tệ có gốc ngoại tệ cuối năm (của Tiền và Nợ phải thu TK 111, 112, 131), điều chỉnh tăng lợi nhuận theo quy định về giao dịch liên kết...","Rủi ro: Tính toán thiếu các khoản phải điều chỉnh tăng hoặc gộp khoản thu nhập điều chỉnh tăng này vào thu nhập được hưởng ưu đãi miễn giảm thuế TNDN không đúng quy định."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R19":{"ten":"CÁC KHOẢN ĐIỀU CHỈNH LÀM GIẢM LỢI NHUẬN TRƯỚC THUẾ KHÁC","sl1":"Chỉ tiêu [B12] trên Tờ khai 03/TNDN (theo TT80/2021/TT-BTC) hoặc Chỉ tiêu [B11] (theo TT151/2014/TT-BTC).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Tờ khai quyết toán thuế TNDN 03/TNDN.","banChat":"Kiểm soát chặt chẽ các khoản điều chỉnh làm giảm trực tiếp lợi nhuận tính thuế TNDN trong kỳ.","hoSo":"Yêu cầu bắt buộc có bảng giải trình chi tiết từng đồng điều chỉnh giảm tại [B12] kèm chứng từ gốc và Tờ khai 03/TNDN của năm trước liên quan.","hieuChinh":[],"nhom":{"TNDN":["PN","MG"]},"khiDuong":[],"khiAm":[],"chung":["Khi [B12] > 0, thu nhập chịu thuế TNDN bị giảm xuống trực tiếp. Các khoản hợp lệ tại [B12] thường là: Lãi chênh lệch tỷ giá do đánh giá lại cuối năm của Tiền mặt, Tiền gửi, Phải thu khách hàng (TK 111, 112, 131); hoặc các khoản chi phí trích trước năm trước đã bị loại tại [B4] năm trước nay đã thực chi đủ hồ sơ.","Rủi ro: Kế toán điền nhầm các khoản thu nhập miễn thuế (đáng lẽ ở [C2]) hoặc điền khống số liệu vào [B12] để giảm số thuế phải nộp mà không có hồ sơ chứng minh khoản đó đã từng bị tính thuế/loại trừ ở kỳ trước."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R20":{"ten":"CHUYỂN LỖ VÀ BÙ TRỪ LÃI, LỖ","sl1":"Chỉ tiêu [C3] trên Tờ khai quyết toán thuế TNDN mẫu 03/TNDN (Phụ lục 03-2/TNDN).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Tờ khai quyết toán thuế TNDN 03/TNDN.","banChat":"Kiểm tra tính hợp lệ của số lỗ từ các năm trước chuyển sang trừ vào thu nhập chịu thuế năm hiện tại.","hoSo":"Đối chiếu Phụ lục 03-2/TNDN với Tờ khai 03/TNDN của 5 năm liền kề trước đó và toàn bộ Biên bản thanh tra, kiểm tra thuế (nếu có) để cập nhật số lỗ thực tế còn được phép chuyển.","hieuChinh":[],"nhom":{"TNDN":["PN","MG"]},"khiDuong":[],"khiAm":[],"chung":["3 lỗi sai phổ biến nhất bị cơ quan thuế xuất toán tại [C3]: (1) Chuyển lỗ quá thời hạn 05 năm liên tục kể từ năm tiếp sau năm phát sinh lỗ; (2) Các năm trước đã qua thanh tra, kiểm tra thuế và bị giảm lỗ (hoặc chuyển từ lỗ sang lãi), nhưng kế toán vẫn lấy số lỗ trên tờ khai quyết toán cũ ban đầu để chuyển sang năm nay; (3) Bù trừ lãi/lỗ sai nguyên tắc giữa hoạt động chuyển nhượng bất động sản, hoạt động được hưởng ưu đãi thuế và hoạt động SXKD thông thường."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R21":{"ten":"THUẾ TNDN ĐƯỢC MIỄN, GIẢM TRONG KỲ","sl1":"Chỉ tiêu [C12] (miễn) + [C13] (giảm) trên Tờ khai 03/TNDN (theo TT80/2021/TT-BTC) hoặc Chỉ tiêu [C12] (theo TT151/2014/TT-BTC).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Tờ khai quyết toán thuế TNDN 03/TNDN.","banChat":"Thẩm định điều kiện, mức thuế suất ưu đãi, thời gian miễn thuế, giảm thuế TNDN của doanh nghiệp.","hoSo":"Rà soát Giấy chứng nhận đăng ký đầu tư, văn bản xác nhận ưu đãi, Phụ lục ưu đãi thuế TNDN (03-3A, 03-3B, 03-3C) và bảng phân bổ chi phí giữa hoạt động ưu đãi và không ưu đãi.","hieuChinh":["App lấy rộng hơn tài liệu: [C10] (= C11 + C12 + C13, gồm cả thuế chênh lệch do thuế suất ưu đãi) + [C14] + [C15], đồng thời hiển thị riêng C12, C13."],"nhom":{"TNDN":["PN","MG"]},"khiDuong":[],"khiAm":[],"chung":["Khi doanh nghiệp kê khai có số thuế TNDN được miễn, giảm (> 0), cơ quan thuế sẽ kiểm tra: (1) Dự án đầu tư/ngành nghề/địa bàn có thực sự đáp ứng điều kiện ưu đãi theo Luật Thuế TNDN không; (2) Xác định năm đầu tiên có doanh thu và năm đầu tiên có thu nhập chịu thuế đã đúng chưa; (3) Doanh nghiệp có hạch toán riêng thu nhập từ hoạt động được ưu đãi và thu nhập không được ưu đãi (lãi tiền gửi, lãi cho vay, thanh lý tài sản, thương mại thông thường...) hay gộp chung tất cả để hưởng ưu đãi; (4) Đối với đợt giảm 30% thuế TNDN theo Nghị quyết Quốc hội (nếu có áp dụng ở các năm cụ thể), doanh nghiệp có đáp ứng điều kiện tổng doanh thu không?"],"canhBao":{"muc":"Vàng","dieuKien":null}},"R22":{"ten":"CÓ HOẠT ĐỘNG BÁN HHDV THU NGOẠI TỆ NHƯNG KHÔNG CÓ ĐIỀU CHỈNH TĂNG/GIẢM LỢI NHUẬN KHÁC","sl1":"Chỉ tiêu [B7] (Điều chỉnh tăng lợi nhuận trước thuế khác) trên Tờ khai 03/TNDN.","sl2":"Chỉ tiêu [B12] (theo TT80/2021) hoặc Chỉ tiêu [B11] (theo TT151/2014) (Điều chỉnh giảm lợi nhuận trước thuế khác) trên Tờ khai 03/TNDN.","congThuc":"Chênh lệch = SL1 - SL2 (Kiểm tra khi DN có doanh thu xuất khẩu hoặc giao dịch ngoại tệ nhưng SL1 = 0 và SL2 = 0)","dieuKien":"Doanh nghiệp có phát sinh doanh thu xuất khẩu (PL 03-1A [05] > 0; chỉ tiêu [29] trên 01/GTGT gồm cả hàng hóa chịu thuế 0% không phải xuất khẩu nên chỉ dùng tham khảo) hoặc có số dư ngoại tệ cuối kỳ.","banChat":"Phát hiện rủi ro doanh nghiệp có giao dịch ngoại tệ nhưng không đánh giá lại chênh lệch tỷ giá cuối năm hoặc không điều chỉnh chênh lệch tỷ giá chưa thực hiện khi quyết toán thuế TNDN.","hoSo":"Kiểm tra bút toán đánh giá lại ngoại tệ ngày 31/12 trên TK 4131, 515, 635. Tách riêng phần lãi/lỗ đánh giá lại của TK 1112, 1122, 131 để đưa vào chỉ tiêu [B12] (nếu lãi) hoặc [B7] (nếu lỗ).","hieuChinh":["Điều kiện kích hoạt: app dùng doanh thu xuất khẩu PL 03-1A [05], số dư/phát sinh 1112, 1122, 413 thay cho chỉ tiêu [29]."],"nhom":{"GTGT":["DT"],"TNDN":["DT"],"Khac":["KH"]},"khiDuong":[],"khiAm":[],"chung":["Theo chế độ kế toán (TT200/TT133), cuối năm tài chính DN bắt buộc phải đánh giá lại toàn bộ các khoản mục tiền tệ có gốc ngoại tệ (TK 1112, 1122, 131, 331, 341...) theo tỷ giá giao dịch thực tế cuối kỳ và kết chuyển lãi/lỗ vào TK 515 / TK 635.","Tuy nhiên, theo pháp luật thuế TNDN (TT 96/2015/TT-BTC; từ kỳ 2025 đối chiếu NĐ 320/2025): Chênh lệch tỷ giá do đánh giá lại cuối năm của Tiền mặt, Tiền gửi ngân hàng và Các khoản nợ phải thu (TK 111, 112, 131) KHÔNG được tính vào chi phí được trừ hoặc thu nhập chịu thuế TNDN (chỉ chênh lệch tỷ giá đánh giá lại các khoản Nợ phải trả mới được tính). Do đó, nếu DN có ngoại tệ mà cả [B7] và [B12] đều bằng 0, chứng tỏ DN quên đánh giá lại tỷ giá cuối kỳ hoặc quên loại trừ lãi/lỗ tỷ giá của Tiền và Nợ phải thu trên 03/TNDN."],"canhBao":{"muc":"Đỏ","dieuKien":null}},"R23":{"ten":"CHỈ TIÊU PHẢI THU NGẮN HẠN CỦA KHÁCH HÀNG","sl1":"Mã số 131 trên Bảng cân đối kế toán (Số dư cuối năm).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Bảng cân đối kế toán.","banChat":"Đánh giá rủi ro về điều kiện thanh toán qua ngân hàng đối với các khoản doanh thu bán trả chậm (đặc biệt là doanh thu xuất khẩu) và rủi ro thu tiền bán hàng để ngoài sổ sách.","hoSo":"Lập Bảng tổng hợp tuổi nợ Phải thu khách hàng (Aging Schedule), rà soát thời hạn thanh toán trên các hợp đồng xuất khẩu và chuẩn bị đầy đủ Biên bản đối chiếu công nợ tại ngày 31/12.","hieuChinh":["Bỏ mốc '31/12 đối với nợ quá hạn' (chưa tìm được căn cứ); bổ sung căn cứ theo thời kỳ."],"nhom":{"GTGT":["KT","HT"]},"khiDuong":[],"khiAm":[],"chung":["Rủi ro 1 (Đối với doanh nghiệp xuất khẩu): Theo điều kiện khấu trừ, hoàn thuế hàng xuất khẩu (Điều 16 TT 219/2013 cho kỳ trước 01/7/2025; Luật GTGT 48/2024, NĐ 181/2025 từ 01/7/2025), đối với hàng hóa, dịch vụ xuất khẩu thanh toán trả chậm, nếu đến thời hạn thanh toán theo hợp đồng mà DN không có chứng từ thanh toán qua ngân hàng hợp lệ, DN không được khấu trừ và không được hoàn thuế GTGT đầu vào tương ứng với tỷ lệ doanh thu xuất khẩu đó.","Rủi ro 2 (Đối với bán hàng nội địa): Số dư Nợ TK 131 lớn bất thường và kéo dài qua nhiều năm có thể là dấu hiệu khách hàng thực tế đã thanh toán bằng tiền mặt hoặc chuyển vào tài khoản cá nhân của chủ doanh nghiệp nhưng kế toán vẫn treo nợ trên BCTC."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R24":{"ten":"CHỈ TIÊU PHẢI THU NGẮN HẠN KHÁC","sl1":"Mã số 136 (TT200) hoặc Mã số 134 (TT133 Mẫu B01a) hoặc Mã số 133 (TT133 Mẫu B01b) trên Bảng CĐKT.","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Bảng CĐKT và Thuyết minh BCTC.","banChat":"Phát hiện rủi ro giấu doanh thu qua tài khoản trung gian (TK 138), hàng thiếu chờ xử lý (TK 1381) hoặc tạm ứng/cho mượn tiền ảo (TK 141, 1388).","hoSo":"Rà soát chi tiết Sổ cái TK 1381, 1388, 141, 244. Thu hồi hoặc hoàn ứng các khoản tạm ứng cá nhân lớn trước ngày khóa sổ; đảm bảo không phát sinh cho cá nhân/bên liên kết mượn tiền không lãi suất khi công ty đang có dư nợ vay.","hieuChinh":[],"nhom":{"GTGT":["DT"],"TNDN":["DT","CP"],"Khac":["HĐ"]},"khiDuong":[],"khiAm":[],"chung":["Khi số dư Phải thu ngắn hạn khác lớn, cơ quan thuế tập trung vào 3 trọng điểm: (1) Tạm ứng cá nhân (TK 141) hoặc Cho mượn tiền không tính lãi (TK 1388) với số tiền lớn trong khi DN đang đi vay ngân hàng và hạch toán chi phí lãi vay (TK 635) -> CQT sẽ xuất toán chi phí lãi vay tương ứng hoặc ấn định doanh thu lãi tiền cho vay theo quy định về ấn định thuế của Luật Quản lý thuế.","(2) Treo giá trị hàng hóa đã xuất bán hoặc doanh thu trích trước trên TK 1388 / TK 1381 (Tài sản thiếu chờ xử lý) nhưng thực chất đã bán thu tiền mà không lập hóa đơn và không kê khai thuế GTGT, TNDN.","(3) Hạch toán thuế GTGT đầu vào chưa kê khai vào TK 1388 sai quy định."],"canhBao":{"muc":"Đỏ","dieuKien":null}},"R25":{"ten":"CHỈ TIÊU DỰ PHÒNG PHẢI THU NGẮN HẠN VÀ DÀI HẠN KHÓ ĐÒI","sl1":"Mã số 137 + 219 (TT200) hoặc Mã số 136 (TT133 Mẫu B01a) hoặc Mã số 135 + 215 (TT133 Mẫu B01b) trên Bảng CĐKT (Giá trị tuyệt đối).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = |SL1|","dieuKien":"Khai thác trên Bảng cân đối kế toán.","banChat":"Kiểm tra điều kiện trích lập dự phòng nợ phải thu khó đòi tính vào chi phí được trừ TNDN và hệ quả đối với thuế GTGT đầu vào của hàng xuất khẩu.","hoSo":"Kiểm tra bộ hồ sơ trích lập dự phòng của từng khách hàng tại ngày 31/12 theo đúng Thông tư 48/2019/TT-BTC. Nếu chưa đủ biên bản xác nhận nợ hoặc chứng từ đòi nợ hợp lệ, cần tự giác loại tại chỉ tiêu [B4].","hieuChinh":["Bỏ điều kiện 'đòi nợ ít nhất 3 lần' – TT 48/2019 không quy định số lần."],"nhom":{"GTGT":["KT"],"TNDN":["CP"]},"khiDuong":[],"khiAm":[],"chung":["Rủi ro 1 (Về Chi phí được trừ TNDN - CP): Theo Thông tư 48/2019/TT-BTC và Thông tư 24/2022/TT-BTC, khoản trích lập dự phòng nợ phải thu khó đòi (ghi Nợ TK 642 / Có TK 2293) sẽ bị xuất toán 100% nếu thiếu một trong các điều kiện: Hợp đồng kinh tế gốc, Biên bản đối chiếu công nợ tại thời điểm cuối năm (hoặc văn bản đề nghị đối chiếu xác nhận nợ / văn bản đòi nợ đã gửi, có dấu bưu điện hoặc xác nhận của đơn vị chuyển phát), chứng từ chứng minh nợ đã quá hạn thanh toán từ 06 tháng trở lên và trích đúng tỷ lệ (30%, 50%, 70%, 100%).","Rủi ro 2 (Về Thuế GTGT đầu vào - KT): Nếu khoản nợ khó đòi trích lập dự phòng là của khách hàng xuất khẩu nước ngoài, điều đó đồng nghĩa khoản xuất khẩu không thu được tiền qua ngân hàng -> Bị loại thuế GTGT đầu vào tương ứng đã khấu trừ/hoàn thuế."],"canhBao":{"muc":"Đỏ","dieuKien":null}},"R26":{"ten":"CHỈ TIÊU TÀI SẢN DỞ DANG DÀI HẠN HOẶC XDCB DỞ DANG","sl1":"Mã số 240 (TT200 & TT133 Mẫu B01b) hoặc Mã số 170 (TT133 Mẫu B01a) trên Bảng CĐKT.","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Bảng cân đối kế toán.","banChat":"Phát hiện rủi ro công trình/dự án đã hoàn thành đưa vào sử dụng hoặc đã bàn giao cho khách hàng nhưng vẫn treo trên TK 241/154 dài hạn.","hoSo":"Tách rõ theo dõi chi tiết từng công trình/hạng mục trên TK 2411, 2412. Rà soát biên bản nghiệm thu đưa vào sử dụng để kịp thời kết chuyển sang TK 211 hoặc ghi nhận doanh thu.","hieuChinh":[],"nhom":{"GTGT":["DT","KT","CP"]},"khiDuong":[],"khiAm":[],"chung":["Rủi ro 1: Đơn vị hoạt động sản xuất, xây dựng hoặc kinh doanh BĐS đã nhận tiền ứng trước của khách hàng, tập hợp chi phí trên TK 241/154 và thực tế đã bàn giao hạng mục/công trình nhưng chưa kết chuyển ghi nhận doanh thu và chưa kê khai thuế GTGT đầu ra.","Rủi ro 2: Dự án đầu tư xây dựng nhà xưởng, máy móc của doanh nghiệp đã hoàn thành đi vào hoạt động hoặc thuộc diện phải kê khai riêng tờ khai hoàn thuế dự án đầu tư (Mẫu 02/GTGT) nhưng DN kê khai lẫn vào mẫu 01/GTGT, hoặc hạch toán lẫn các chi phí quản lý không phục vụ dự án vào TK 241."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R27":{"ten":"CHỈ TIÊU NGƯỜI MUA TRẢ TIỀN TRƯỚC NGẮN HẠN VÀ DÀI HẠN","sl1":"Mã số 312 + 332 (TT200) hoặc Mã số 312 (TT133 Mẫu B01a) hoặc Mã số 412 + 422 (TT133 Mẫu B01b) trên Bảng CĐKT (Số dư Có TK 131).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Bảng CĐKT và Thuyết minh BCTC.","banChat":"Trọng điểm kiểm tra hành vi thu tiền trước của khách hàng nhưng không lập hóa đơn đúng thời điểm hoặc đã giao hàng/hoàn thành dịch vụ nhưng trốn doanh thu.","hoSo":"Kiểm tra chi tiết từng khách hàng có số dư Có TK 131 cuối năm: Đối chiếu với Hợp đồng kinh tế xem là hợp đồng bán hàng hóa (hợp lệ nếu chưa giao hàng) hay hợp đồng dịch vụ (bắt buộc phải xuất hóa đơn khi thu tiền, trừ khoản tiền đặt cọc đảm bảo thực hiện hợp đồng dịch vụ chuyên ngành theo quy định).","hieuChinh":[],"nhom":{"GTGT":["DT"],"TNDN":["DT"],"Khac":["HĐ"]},"khiDuong":[],"khiAm":[],"chung":["Rủi ro 1 (Hoạt động cung cấp dịch vụ): Theo Khoản 2 Điều 9 Nghị định 123/2020/NĐ-CP (và NĐ 70/2025/NĐ-CP), thời điểm lập hóa đơn đối với cung cấp dịch vụ là thời điểm hoàn thành việc cung cấp dịch vụ hoặc thời điểm thu tiền trước (không phân biệt đã cung cấp dịch vụ hay chưa). Do đó, nếu DN kinh doanh dịch vụ có Số dư Có TK 131 (Mã 312 > 0), cơ quan thuế sẽ kết luận ngay DN thu tiền dịch vụ mà không lập hóa đơn -> Xử phạt hành vi lập hóa đơn sai thời điểm/không lập hóa đơn và truy thu thuế GTGT đầu ra ngay tại kỳ nhận tiền.","Rủi ro 2 (Hoạt động bán hàng hóa, xây lắp): Hàng hóa thực tế đã xuất giao, công trình đã hoàn thành nghiệm thu và khách hàng đã chuyển tiền thanh toán (ghi Có TK 131), nhưng kế toán chưa xuất hóa đơn nên không ghi nhận Nợ TK 131 / Có TK 511, làm TK 131 treo dư Có giả tạo để lùi doanh thu sang năm sau."],"canhBao":{"muc":"Đỏ","dieuKien":"đối với DN dịch vụ"}},"R28":{"ten":"CHỈ TIÊU PHẢI TRẢ NGƯỜI LAO ĐỘNG","sl1":"Mã số 314 (TT200 & TT133 Mẫu B01a) hoặc Mã số 414 (TT133 Mẫu B01b) trên Bảng CĐKT (Số dư Có TK 334 cuối năm).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Bảng cân đối kế toán.","banChat":"Kiểm tra điều kiện thực chi đối với chi phí tiền lương, tiền công, tiền thưởng đã hạch toán vào chi phí tính thuế TNDN trong năm.","hoSo":"Đối chiếu Số dư Có TK 334 ngày 31/12 với các Phiếu chi / Ủy nhiệm chi thanh toán lương tháng 12 và thưởng Tết trong quý 1 năm sau (trước ngày 31/03). Phần chưa chi hết phải chủ động loại tại chỉ tiêu [B4].","hieuChinh":["Hạn quyết toán 31/03 áp dụng cho năm tài chính trùng năm dương lịch; căn cứ từ kỳ 2025 cần đối chiếu NĐ 320/2025."],"nhom":{"TNDN":["CP"],"Khac":["KH"]},"khiDuong":[],"khiAm":[],"chung":["Theo Điểm 2.6 Khoản 2 Điều 4 TT 96/2015/TT-BTC (từ kỳ tính thuế 2025 đối chiếu NĐ 320/2025): Các khoản tiền lương, tiền công, tiền thưởng cho người lao động đã hạch toán vào chi phí SXKD trong kỳ nhưng thực tế không chi trả hoặc đến hết thời hạn nộp hồ sơ quyết toán thuế năm (ngày 31/03 năm sau) vẫn chưa chi trả thì KHÔNG được tính vào chi phí được trừ của năm quyết toán (trừ trường hợp DN có trích lập quỹ dự phòng tiền lương của năm sau tối đa không quá 17% quỹ lương thực hiện và doanh nghiệp không bị lỗ).","Rủi ro: Có số dư Có TK 334 tại ngày 31/12 nhưng từ ngày 01/01 đến 31/03 năm sau doanh nghiệp chưa chi hết số dư này hoặc trích lập dự phòng lương khi kết quả kinh doanh trong năm đang bị lỗ."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R29":{"ten":"RỦI RO TRÍCH TRƯỚC CÁC CHI PHÍ PHẢI TRẢ KHÔNG ĐÚNG QUY ĐỊNH","sl1":"Mã số 315 + 333 (TT200) trên Bảng CĐKT (Số dư Có TK 335). TT133 không có dòng riêng: TK 335 gộp trong 'Phải trả khác' (mã 315 B01a, 415 B01b) nên lấy dư Có TK 335 trên BCĐTK. Mã 417, 426 của B01b là dự phòng phải trả (thuộc R32).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Bảng cân đối kế toán.","banChat":"Kiểm tra tính hợp pháp của các khoản chi phí trích trước vào giá vốn/chi phí trong năm nhưng chưa thanh toán tại thời điểm cuối năm.","hoSo":"Mở Sổ chi tiết TK 335 tại ngày 31/12, kiểm tra từng khoản trích trước: Phải có hợp đồng, biên bản nghiệm thu hoàn thành công việc trong năm tài chính và hóa đơn về trước kỳ quyết toán, hoặc bảng tính lãi vay lũy kế đúng kỳ hạn.","hieuChinh":["Mã số TT133: mã 315 (B01a) là 'Phải trả khác' gồm cả TK 338; mã 417, 426 (B01b) là dự phòng phải trả – không dùng trực tiếp cho R29.","Lãi vay trích trước đúng kỳ hạn hợp đồng vay là hợp lệ, không thuộc diện 'xuất toán ngay'."],"nhom":{"TNDN":["CP"]},"khiDuong":[],"khiAm":[],"chung":["TK 335 (Chi phí phải trả) là tài khoản thường bị lạm dụng để trích trước chi phí khống vào cuối năm nhằm làm giảm thuế TNDN phải nộp.","Các trường hợp bị cơ quan thuế xuất toán ngay: (1) Trích trước chi phí nhưng đến thời điểm quyết toán thuế (31/03 năm sau) vẫn chưa có hóa đơn, chứng từ hợp pháp hoặc hàng hóa dịch vụ chưa thực tế phát sinh; (2) Trích trước các khoản không có căn cứ (hợp đồng, kỳ hạn, khối lượng đã thực hiện) hoặc không gắn với doanh thu đã ghi nhận trong kỳ; lãi vay trích trước đúng kỳ hạn hợp đồng vẫn hợp lệ; (3) Hạch toán nhầm các khoản dự phòng phải trả (bảo hành) vào TK 335."],"canhBao":{"muc":"Đỏ","dieuKien":null}},"R30":{"ten":"CHỈ TIÊU DOANH THU CHƯA THỰC HIỆN NGẮN HẠN VÀ DÀI HẠN","sl1":"Mã số 318 (Ngắn hạn) + Mã số 336 (Dài hạn) trên Bảng CĐKT theo TT200 (Số dư Có TK 3387).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"BCTC theo Thông tư 200/2014/TT-BTC (hoặc số dư TK 3387 trên BCĐTK theo TT133).","banChat":"Kiểm tra nghĩa vụ thuế GTGT, thuế TNDN và thời điểm phân bổ doanh thu đối với các khoản tiền thu trước nhiều kỳ (TK 3387).","hoSo":"Lập Bảng theo dõi phân bổ TK 3387 chi tiết theo từng hợp đồng, thời hạn thuê/cung cấp dịch vụ, số hóa đơn đã xuất và số doanh thu đã kết chuyển vào TK 511 trong năm.","hieuChinh":[],"nhom":{"GTGT":["DT"],"TNDN":["DT"],"Khac":["HĐ"]},"khiDuong":[],"khiAm":[],"chung":["Khi có số dư trên TK 3387, cơ quan thuế rà soát: (1) Về Thuế GTGT: Khi thu tiền trước nhiều kỳ (cho thuê tài sản, cho thuê hạ tầng, hội viên...), doanh nghiệp đã xuất hóa đơn GTGT và kê khai nộp đủ 100% thuế GTGT đầu ra tại thời điểm thu tiền chưa?","(2) Về Thuế TNDN: Doanh nghiệp có phân bổ đúng số tháng/kỳ đã thực hiện trong năm từ TK 3387 sang TK 511 hay không? Hoặc đối với các dịch vụ đã hoàn thành trong năm nhưng kế toán cố tình treo vào TK 3387 để hoãn nộp thuế TNDN sang năm sau."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R31":{"ten":"CHỈ TIÊU THUẾ TNDN HOÃN LẠI PHẢI TRẢ","sl1":"Mã số 341 trên Bảng CĐKT theo TT200 (Số dư Có TK 347).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"BCTC theo Thông tư 200/2014/TT-BTC.","banChat":"Kiểm tra các khoản chênh lệch tạm thời chịu thuế giữa kế toán và thuế làm phát sinh nghĩa vụ thuế TNDN hoãn lại phải trả.","hoSo":"Kiểm tra Bảng xác định chênh lệch tạm thời chịu thuế, đối chiếu sự biến động của Mã số 341 với chỉ tiêu Chi phí thuế TNDN hoãn lại (Mã số [52] trên BCKQKD) và các chỉ tiêu điều chỉnh trên 03/TNDN.","hieuChinh":[],"nhom":{"TNDN":["PN","MG"]},"khiDuong":[],"khiAm":[],"chung":["Số dư trên Mã số 341 (TK 347) phản ánh khoản thuế TNDN sẽ phải nộp trong tương lai phát sinh từ các khoản chênh lệch tạm thời chịu thuế trong năm hiện tại (ví dụ: khấu hao TSCĐ theo thuế nhanh hơn theo kế toán, hoặc ghi nhận doanh thu kế toán trước khi phát sinh nghĩa vụ thuế).","Rủi ro: Doanh nghiệp xác định sai chênh lệch tạm thời để làm giảm số thuế TNDN hiện hành phải nộp trong năm, hoặc khi khoản chênh lệch tạm thời này hoàn nhập ở các năm sau nhưng quên không điều chỉnh tăng thu nhập chịu thuế trên Tờ khai 03/TNDN."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R32":{"ten":"TRÍCH LẬP DỰ PHÒNG KHÔNG ĐÚNG QUY ĐỊNH","sl1":"Tổng hợp các chỉ tiêu dự phòng trên Bảng CĐKT: TT200 (Mã 122, 137, 149, 219, 254, 321, 342); TT133 Mẫu B01a (Mã 124, 136, 142, 318); TT133 Mẫu B01b (Mã 122, 135, 142, 215, 252, 417, 426).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = Tổng giá trị tuyệt đối các khoản dự phòng","dieuKien":"Khai thác trên Bảng cân đối kế toán.","banChat":"Kiểm tra toàn diện tính hợp pháp của tất cả các khoản trích lập dự phòng trên BCTC (Chứng khoán, Nợ khó đòi, Hàng tồn kho, Đầu tư tài chính, Dự phòng phải trả bảo hành).","hoSo":"App cần hiển thị cảnh báo chi tiết cho từng mã dự phòng có số dư khác 0 và yêu cầu người dùng tích chọn checklist hồ sơ theo Thông tư 48/2019/TT-BTC & Thông tư 24/2022/TT-BTC.","hieuChinh":["Dự phòng tổn thất đầu tư: TT 48/2019 căn cứ BCTC của đơn vị nhận vốn; chỉ yêu cầu BCTC đã kiểm toán khi đơn vị đó thuộc diện kiểm toán."],"nhom":{"TNDN":["CP"]},"khiDuong":[],"khiAm":[],"chung":["Mọi khoản trích lập dự phòng đều làm tăng trực tiếp chi phí trong kỳ (TK 632, 635, 641, 642) và giảm thuế TNDN phải nộp. Do đó, cơ quan thuế kiểm tra cực kỳ khắt khe theo Thông tư 48/2019/TT-BTC và Thông tư 24/2022/TT-BTC:","- Dự phòng giảm giá hàng tồn kho (Mã 149/142): Xuất toán nếu hàng tồn kho không có hóa đơn hợp pháp, không có biên bản kiểm kê hoặc không có chứng cứ chứng minh giá trị thuần có thể thực hiện được thấp hơn giá gốc tại ngày 31/12.","- Dự phòng tổn thất đầu tư tài chính dài hạn (Mã 254/124): Xuất toán nếu không có BCTC của đơn vị nhận vốn góp (BCTC đã kiểm toán nếu đơn vị đó thuộc diện phải kiểm toán) chứng minh vốn chủ sở hữu thực tế thấp hơn vốn đầu tư của chủ sở hữu.","- Dự phòng phải trả / bảo hành sản phẩm, công trình xây lắp (Mã 321, 342/318): Xuất toán nếu trích vượt mức 5% tổng doanh thu bán hàng/tổng giá trị hợp đồng xây lắp, hoặc hết thời hạn bảo hành mà không hoàn nhập giảm chi phí."],"canhBao":{"muc":"Đỏ","dieuKien":null}},"R33":{"ten":"TRÍCH LẬP QUỸ PHÁT TRIỂN KHOA HỌC VÀ CÔNG NGHỆ","sl1":"Mã số 343 (TT200) hoặc Mã số 320 (TT133 Mẫu B01a) hoặc Mã số 427 (TT133 Mẫu B01b) trên Bảng CĐKT (Số dư Có TK 356).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Bảng cân đối kế toán.","banChat":"Giám sát việc trích lập và sử dụng Quỹ phát triển khoa học và công nghệ được trừ trước khi tính thuế TNDN.","hoSo":"Kiểm tra Phụ lục 03-6/TNDN (Báo cáo trích lập, điều chuyển và sử dụng Quỹ phát triển KH&CN) qua chu kỳ 5 năm để cảnh báo số quỹ sắp hết hạn 5 năm chưa giải ngân đủ 70%.","hieuChinh":["Số trích quỹ KH&CN nằm ở chỉ tiêu [C5] (tài liệu gốc ghi [C6] – là thu nhập tính thuế sau khi trích quỹ)."],"nhom":{"TNDN":["CP","PN","MG"]},"khiDuong":[],"khiAm":[],"chung":["Theo Luật TNDN trước 2025, doanh nghiệp được trích tối đa 10% thu nhập tính thuế hàng năm để lập Quỹ phát triển KH&CN (Chỉ tiêu [C5] trên 03/TNDN); mức trích và thời hạn sử dụng theo Luật TNDN 67/2025 cần đối chiếu.","Rủi ro cực lớn: Trong thời hạn 05 năm kể từ năm kế tiếp năm trích lập, nếu doanh nghiệp không sử dụng, sử dụng không hết 70% số quỹ đã trích hoặc sử dụng sai mục đích, doanh nghiệp sẽ bị truy thu thuế TNDN tính trên phần quỹ đã trích mà không sử dụng hoặc sử dụng sai mục đích, ĐỒNG THỜI phải nộp tiền lãi phát sinh từ số thuế TNDN thu hồi đó."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R34":{"ten":"CHỈ TIÊU TIỀN THU KHÁC TỪ HOẠT ĐỘNG SẢN XUẤT KINH DOANH","sl1":"Mã số [06] trên Báo cáo Lưu chuyển tiền tệ (theo phương pháp trực tiếp).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Doanh nghiệp lập Báo cáo Lưu chuyển tiền tệ theo phương pháp trực tiếp.","banChat":"Phát hiện các khoản dòng tiền thu từ hoạt động kinh doanh nhưng không nằm ở dòng tiền thu bán hàng chính (Mã [01]), tiềm ẩn nguy cơ bỏ sót doanh thu tính thuế.","hoSo":"Bóc tách chi tiết cấu thành Mã số [06] trên LCTT: Khoản nào là thu hoàn thuế GTGT, thu hồi tạm ứng, nhận ký cược/ký quỹ (không chịu thuế) và khoản nào là thu nhập chịu thuế (TK 711, 511).","hieuChinh":[],"nhom":{"GTGT":["DT"],"TNDN":["DT"],"Khac":["HĐ","KH"]},"khiDuong":[],"khiAm":[],"chung":["Khi Mã số [06] trên LCTT phát sinh số tiền lớn, cơ quan thuế sẽ yêu cầu mở sổ chi tiết TK 111, 112 đối ứng với các tài khoản tạo nên Mã số [06] (thường là TK 711, 1388, 3388, 3386, 141...).","Rủi ro: Nhiều doanh nghiệp thu tiền bán phế liệu, thanh lý vật tư/tài sản, tiền dịch vụ phụ trợ, hoặc tiền khách hàng thanh toán qua tài khoản phải thu/phải trả khác (TK 1388, 3388) và bị phần mềm gom vào Mã số [06] nhưng thực chất là doanh thu bán hàng hóa, dịch vụ chưa xuất hóa đơn và chưa kê khai thuế GTGT, TNDN."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R35":{"ten":"CHỈ TIÊU TIỀN CHI KHÁC CHO HOẠT ĐỘNG SẢN XUẤT KINH DOANH","sl1":"Mã số [07] trên Báo cáo Lưu chuyển tiền tệ (theo phương pháp trực tiếp - Giá trị tuyệt đối).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = |SL1|","dieuKien":"Doanh nghiệp lập Báo cáo Lưu chuyển tiền tệ theo phương pháp trực tiếp.","banChat":"Kiểm tra các khoản chi tiền mặt/ngân hàng bất thường ngoài chi trả nhà cung cấp, tiền lương, lãi vay, thuế.","hoSo":"Phân tích chi tiết các bút toán Có TK 111, 112 được gom vào Mã số [07] trên Báo cáo LCTT để rà soát chứng từ gốc và nghĩa vụ khấu trừ thuế TNCN tại nguồn.","hieuChinh":[],"nhom":{"GTGT":["DT"],"TNDN":["DT","CP"],"Khac":["HĐ","KH"]},"khiDuong":[],"khiAm":[],"chung":["Rủi ro 1 (Về Doanh thu & Hóa đơn): Doanh nghiệp chi tiền để thực hiện các hoạt động mua hàng khuyến mại, quà biếu tặng khách hàng, chi hộ... hoặc chi phí sản xuất kinh doanh nhưng không hạch toán doanh thu tương ứng và không lập hóa đơn đối với hàng biếu tặng.","Rủi ro 2 (Về Chi phí được trừ & Thuế TNCN/FCT): Trong Mã số [07] thường chứa các khoản chi phạt vi phạm, chi tiếp khách/hoa hồng môi giới bằng tiền mặt cho cá nhân (chưa khấu trừ 10% thuế TNCN vãng lai), chi phúc lợi vượt quá 01 tháng lương bình quân thực tế (mức khống chế theo TT 96/2015; từ kỳ 2025 đối chiếu NĐ 320/2025), hoặc chi tạm ứng cá nhân số tiền lớn."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R36":{"ten":"CHỈ TIÊU TIỀN CHI CHO VAY, MUA CÁC CÔNG CỤ NỢ CỦA ĐƠN VỊ KHÁC","sl1":"Mã số [23] trên Báo cáo Lưu chuyển tiền tệ (Giá trị tuyệt đối).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = |SL1|","dieuKien":"Khai thác trên Báo cáo Lưu chuyển tiền tệ.","banChat":"Phát hiện hoạt động cho vay vốn của doanh nghiệp qua dòng tiền đầu tư và các hệ lụy trực tiếp về ấn định lãi vay, loại chi phí lãi vay và phân bổ thuế GTGT đầu vào.","hoSo":"Tách bạch rõ trên thuyết minh BCTC: Khoản nào tại Mã số [23] là Tiền gửi ngân hàng có kỳ hạn (Lãi tiền gửi ngân hàng là khoản thu tài chính KHÔNG phải kê khai, tính nộp thuế GTGT và KHÔNG phải phân bổ VAT đầu vào dùng chung) và khoản nào là Tiền cho tổ chức/cá nhân vay.","hieuChinh":["Căn cứ ấn định thuế theo thời kỳ (Luật QLT 38/2019 → Luật QLT 108/2025); thay '20%' bằng thuế suất áp dụng."],"nhom":{"GTGT":["DT","KT"],"TNDN":["DT","CP"],"Khac":["HĐ"]},"khiDuong":[],"khiAm":[],"chung":["Khi Mã số [23] phát sinh số liệu (< 0 trên LCTT), doanh nghiệp có chi tiền cho tổ chức/cá nhân khác vay hoặc gửi tiết kiệm có kỳ hạn. Cơ quan thuế sẽ lập tức kiểm tra 3 mũi nhọn:","(1) Nếu cho vay không lấy lãi (lãi suất 0%) hoặc lãi suất thấp bất thường: CQT căn cứ quy định về ấn định thuế của Luật Quản lý thuế (Luật 38/2019/QH14; Luật 108/2025/QH15 cho các kỳ áp dụng luật mới – cần đối chiếu điều khoản) để ấn định doanh thu lãi tiền cho vay và truy thu thuế TNDN theo thuế suất áp dụng; đồng thời xuất toán chi phí lãi vay mà DN đang phải trả cho ngân hàng.","(2) Về Hóa đơn: Hoạt động cho vay tiền (của DN không phải tổ chức tín dụng) khi thu lãi bắt buộc phải lập hóa đơn GTGT (thuế suất: Không chịu thuế GTGT).","(3) Về Thuế GTGT đầu vào: Do lãi tiền cho vay là doanh thu không chịu thuế GTGT (Chỉ tiêu [26] trên 01/GTGT), doanh nghiệp có nguy cơ phải phân bổ lại thuế GTGT đầu vào dùng chung (liên kết với chỉ tiêu R04)."],"canhBao":{"muc":"Đỏ","dieuKien":null}},"R37":{"ten":"CHỈ TIÊU THU LÃI TIỀN CHO VAY, CỔ TỨC VÀ LỢI NHUẬN ĐƯỢC CHIA","sl1":"Mã số [27] (TT200) hoặc Mã số [25] (TT133) trên Báo cáo Lưu chuyển tiền tệ.","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = SL1","dieuKien":"Khai thác trên Báo cáo Lưu chuyển tiền tệ.","banChat":"Kiểm tra việc ghi nhận doanh thu hoạt động tài chính (TK 515), xuất hóa đơn đối với lãi tiền cho vay và phân bổ thuế GTGT đầu vào.","hoSo":"Đối chiếu số phát sinh tại Mã số [27]/[25] LCTT với Sổ chi tiết TK 515, Tờ khai 01/GTGT (Chỉ tiêu [26]) và Tờ khai 03/TNDN (Chỉ tiêu [C2]).","hieuChinh":[],"nhom":{"GTGT":["DT","KT"],"TNDN":["DT"],"Khac":["HĐ"]},"khiDuong":[],"khiAm":[],"chung":["Khi có dòng tiền thu tại Mã số [27]/[25] LCTT: (1) Kiểm tra xem khoản thu này đã được ghi nhận đầy đủ vào Có TK 515 trên BCKQKD chưa; (2) Nếu là thu lãi tiền cho vay cá nhân/doanh nghiệp khác: Đã lập hóa đơn không chịu thuế GTGT, kê khai vào chỉ tiêu [26] trên tờ khai 01/GTGT và phân bổ thuế GTGT đầu vào dùng chung chưa?","(3) Về Ưu đãi thuế TNDN: Lãi tiền gửi, lãi tiền cho vay không được hưởng ưu đãi thuế TNDN theo ngành nghề sản xuất chính (trừ lãi tiền gửi không kỳ hạn phát sinh trực tiếp từ hoạt động SXKD ưu đãi theo hướng dẫn chuyên ngành). Cổ tức, lợi nhuận được chia sau thuế từ doanh nghiệp trong nước được miễn thuế TNDN tại chỉ tiêu [C2]."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R38":{"ten":"CHỈ TIÊU TIỀN CHI ĐỂ MUA SẮM, XÂY DỰNG TSCĐ, TÀI SẢN DÀI HẠN KHÁC","sl1":"Mã số [21] trên Báo cáo Lưu chuyển tiền tệ (Giá trị tuyệt đối).","sl2":"Không áp dụng.","congThuc":"Giá trị đánh giá = |SL1|","dieuKien":"Khai thác trên Báo cáo Lưu chuyển tiền tệ.","banChat":"Kiểm tra điều kiện kê khai khấu trừ và hoàn thuế GTGT đối với hoạt động mua sắm TSCĐ và Dự án đầu tư.","hoSo":"Kiểm tra hồ sơ tăng TSCĐ (TK 211) và XDCB dở dang (TK 241) trong kỳ. Rà soát nguyên giá từng xe ô tô dưới 9 chỗ ngồi và quy chế kê khai riêng tờ khai 02/GTGT đối với dự án đầu tư.","hieuChinh":[],"nhom":{"GTGT":["KT"]},"khiDuong":[],"khiAm":[],"chung":["Rủi ro 1 (Kê khai sai mẫu tờ khai Dự án đầu tư): Nếu khoản tiền chi lớn tại Mã số [21] là chi cho Dự án đầu tư mới/mở rộng thuộc diện phải kê khai riêng trên Tờ khai thuế GTGT dành cho dự án đầu tư (Mẫu 02/GTGT), nhưng kế toán lại kê khai gộp chung vào Tờ khai 01/GTGT của hoạt động SXKD thông thường -> Bị rủi ro xuất toán khi đề nghị hoàn thuế GTGT dự án đầu tư.","Rủi ro 2 (Điều kiện khấu trừ VAT của TSCĐ): Mua xe ô tô chở người từ 9 chỗ ngồi trở xuống (không dùng cho kinh doanh vận tải, du lịch, khách sạn) có trị giá vượt trên 1,6 tỷ đồng nhưng vẫn khấu trừ toàn bộ thuế GTGT đầu vào; hoặc mua sắm TSCĐ chuyên dùng cho hoạt động không chịu thuế GTGT."],"canhBao":{"muc":"Vàng","dieuKien":null}},"R39":{"ten":"Ý KIẾN CỦA KIỂM TOÁN ĐỘC LẬP TRÊN BÁO CÁO TÀI CHÍNH","sl1":"Loại ý kiến kiểm toán trên Báo cáo kiểm toán độc lập (Chấp nhận toàn phần / Chấp nhận từng phần - Ngoại trừ / Không chấp nhận / Từ chối đưa ra ý kiến).","sl2":"Không áp dụng.","congThuc":"Đánh giá định tính theo loại Ý kiến kiểm toán khác 'Chấp nhận toàn phần'","dieuKien":"Báo cáo tài chính thuộc diện kiểm toán độc lập.","banChat":"Đánh giá mức độ tin cậy tổng thể của Báo cáo tài chính và xác định ngay các khoản mục trọng yếu có sai sót thông qua điểm ngoại trừ của Kiểm toán viên.","hoSo":"Trong App Check 39 Chỉ Tiêu Rủi Ro, tạo trường chọn Loại ý kiến kiểm toán và ô nhập nội dung ngoại trừ. Nếu có ý kiến ngoại trừ, hệ thống tự động bật cảnh báo Đỏ và yêu cầu kế toán chuẩn bị sẵn Biên bản kiểm kê, Biên bản đối chiếu công nợ hoặc bút toán điều chỉnh khắc phục các điểm ngoại trừ đó.","hieuChinh":[],"nhom":{"GTGT":["ĐR","KT","HT"],"TNDN":["DT","CP","PN"],"Khac":["HĐ","KH"]},"khiDuong":[],"khiAm":[],"chung":["Khi Báo cáo kiểm toán có Ý kiến Chấp nhận từng phần (Ngoại trừ), Ý kiến Không chấp nhận hoặc Từ chối đưa ra ý kiến:","(1) Hệ thống phân tích rủi ro của Cơ quan thuế sẽ chấm điểm rủi ro ở mức Cao nhất và đưa doanh nghiệp vào danh sách thanh tra, kiểm tra thuế trọng điểm.","(2) Từng đoạn 'Cơ sở của ý kiến kiểm toán ngoại trừ' (ví dụ: Kiểm toán viên không tham gia chứng kiến kiểm kê hàng tồn kho và tiền mặt; chưa thu thập được đầy đủ thư xác nhận công nợ TK 131, 331; doanh nghiệp chưa trích lập hoặc trích thừa dự phòng/khấu hao; ghi nhận doanh thu/chi phí chưa đúng kỳ...) chính là bằng chứng trực tiếp để Đoàn thanh tra thuế yêu cầu giải trình và xuất toán.","(3) Ảnh hưởng trực tiếp đến điều kiện giải quyết hồ sơ hoàn thuế GTGT hoặc hồ sơ miễn giảm thuế."],"canhBao":{"muc":"Đỏ","dieuKien":"khi có ý kiến ngoại trừ/không chấp nhận/từ chối"}}}
const GUIDE_LEGEND = [["DT","Doanh thu tính thuế","Rủi ro ghi nhận thiếu doanh thu, sai kỳ tính thuế GTGT / TNDN hoặc bỏ ngoài sổ sách."],["ĐR","Thuế GTGT đầu ra","Rủi ro kê khai thiếu thuế GTGT đầu ra, áp sai thuế suất hoặc lệch giữa TK 33311 và Tờ khai 01/GTGT."],["KT","Thuế GTGT khấu trừ","Rủi ro kê khai thuế GTGT đầu vào không đủ điều kiện khấu trừ, chưa phân bổ VAT dùng chung, lệch TK 133."],["HT","Thuế GTGT hoàn thuế","Rủi ro sai lệch số thuế đề nghị hoàn, dừng khấu trừ hoặc không đáp ứng điều kiện thanh toán xuất khẩu."],["CP","Chi phí được trừ (TNDN)","Rủi ro hạch toán chi phí không hợp lệ, trích trước/dự phòng sai quy định, thanh toán tiền mặt từ ngưỡng quy định (20 triệu đồng; 05 triệu đồng từ 2025)."],["PN","Thuế TNDN phải nộp","Rủi ro xác định sai nghĩa vụ thuế TNDN phải nộp do chuyển lỗ sai hoặc điều chỉnh giảm lợi nhuận sai."],["UĐ / MG","Ưu đãi, miễn giảm thuế","Rủi ro xác định sai điều kiện ưu đãi, không tách riêng thu nhập khác/tài chính khỏi hoạt động ưu đãi."],["HĐ","Vi phạm về hóa đơn","Rủi ro không lập hóa đơn, lập hóa đơn sai thời điểm (đặc biệt khi thu tiền trước dịch vụ), xuất hàng biếu tặng."],["KH","Rủi ro khác","Rủi ro về thuế TNCN, thuế nhà thầu (FCT), đánh giá chênh lệch tỷ giá cuối kỳ, giao dịch liên kết."]]
const GUIDE_NOTES = ["Căn cứ pháp lý trong tài liệu chủ yếu theo TT 219/2013 (GTGT) và TT 96/2015 (TNDN). Hai thông tư này áp dụng cho các kỳ trước Luật GTGT 48/2024 (01/7/2025) và Luật TNDN 67/2025 (kỳ tính thuế 2025). Với kỳ sau các mốc đó, đối chiếu NĐ 181/2025, NĐ 320/2025 (app đã áp các mốc này).","Tài liệu không ghi mã số BCTC theo TT 99/2025 (chế độ DN từ năm tài chính 2026). App tự quy đổi mã TT 99 qua bảng mapping ở trang Tiêu chí & căn cứ.","Mục III đề xuất ngưỡng 'an toàn' là chênh lệch dưới 1.000 đồng. App dùng dung sai cấu hình được (mặc định 1.000.000 đồng hoặc 0,05% số so sánh) và mức độ Cao/Trung bình/Thấp tính theo số liệu; phân tầng Xanh/Vàng/Đỏ của tài liệu được hiển thị kèm như 'nhóm cảnh báo mặc định'."]
const ANALYSIS = {"R01":{"muc":"NT","yNghia":"Kiểm tra doanh thu khai với cơ quan thuế có nhất quán giữa hai sắc thuế. DT GTGT là số NNT tự khai hằng tháng/quý, DT TNDN là số trên quyết toán năm. Đây thường là tiêu chí CQT xem đầu tiên khi chọn hồ sơ; lệch lớn mà không giải thích được thì sắc thuế khai thấp hơn sẽ bị ấn định hoặc truy thu.","cachDanhGia":"CL ≈ 0: đạt. CL < 0 (DT GTGT < DT TNDN): nghi có doanh thu chưa lập hóa đơn hoặc chưa kê khai GTGT. CL > 0: nghi sót DT tính thuế TNDN. Mọi chênh lệch vượt dung sai đều phải có bảng giải thích theo tháng; khoản nào giải thích được thì nhập vào mục 'Khoản chênh lệch đã giải trình' để app tính lại mức độ.","ruiRo":{"GTGT":"Khai thiếu thuế đầu ra khi DT TNDN > DT GTGT","TNDN":"Khai thiếu DT tính thuế khi DT GTGT > DT TNDN","Khac":"Phạt khai sai 20% số thuế thiếu và tiền chậm nộp 0,03%/ngày"},"lienKet":["R02","R07","R10","R13","R14","R15","R16","R27","R30"],"nguyenNhanBS":["Doanh thu vãng lai ngoại tỉnh hoặc khai tại địa phương khác (khai riêng) không vào tờ khai chính","Chênh lệch tỷ giá quy đổi doanh thu xuất khẩu giữa hóa đơn và sổ"],"hoSoBS":["Danh sách từng hóa đơn gây chênh lệch: số, ngày, giá trị, tài khoản hạch toán"],"luuY":"Lấy tờ khai lần nộp cuối cùng của từng kỳ (đã gộp khai bổ sung). Chọn cơ sở DT thuần hay DT gộp (mã 01) trong cấu hình cho thống nhất với cách CQT dùng."},"R02":{"muc":"TY","yNghia":"Kiểm tra thuế đầu ra kê khai có khớp số thuế đầu ra kế toán đã ghi khi xuất hóa đơn. Tờ khai thấp hơn sổ là dấu hiệu khai thiếu thuế phải nộp.","cachDanhGia":"CL < 0 (tờ khai < sổ): rủi ro khai thiếu thuế GTGT. CL > 0: sổ thiếu bút toán thuế đầu ra, hoặc tờ khai gồm hóa đơn năm trước. Khi số dư cuối 33311 khớp [40] kỳ cuối năm thì chênh lệch nằm ở cách hạch toán hai bên Nợ–Có (app tự hạ mức).","ruiRo":{"GTGT":"Truy thu thuế đầu ra khai thiếu","TNDN":"Gián tiếp, nếu thiếu thuế đầu ra do thiếu doanh thu","Khac":"Phạt khai sai, tiền chậm nộp"},"lienKet":["R01","R07","R09"],"nguyenNhanBS":["Hóa đơn lập cuối kỳ nhưng hạch toán kỳ sau (lệch kỳ)","Sai thuế suất (8%/10%) giữa hóa đơn và sổ","Thuế GTGT vãng lai ngoại tỉnh khai riêng nhưng ghi chung 33311"],"hoSoBS":["Bảng kê hóa đơn điện tử bán ra tải từ hoadondientu.gdt.gov.vn để đối chiếu ba nguồn (HĐĐT – tờ khai – sổ)"],"luuY":"So sánh chính xác hơn: SL2 = PS Có 33311 − PS Nợ 33311 của hóa đơn điều chỉnh giảm, hàng bán bị trả lại (không trừ bút toán khấu trừ Nợ 33311/Có 133 và bút toán nộp tiền Nợ 33311/Có 112)."},"R03":{"muc":"TY","yNghia":"Kiểm tra thuế đầu vào đã khấu trừ trên tờ khai có khớp thuế đầu vào ghi sổ. Tờ khai cao hơn sổ là dấu hiệu khấu trừ hóa đơn không hạch toán, thường gặp khi dùng hóa đơn không có giao dịch thật.","cachDanhGia":"CL > 0 (tờ khai > sổ): mức cao, nghi khấu trừ vượt hoặc hóa đơn không hạch toán. CL < 0: hóa đơn ghi sổ chưa kê khai (được khai bổ sung nếu chưa có quyết định kiểm tra) hoặc thuế không đủ điều kiện vẫn treo 133.","ruiRo":{"GTGT":"Loại khỏi khấu trừ phần kê khai vượt","TNDN":"Hóa đơn không có giao dịch thật thì loại cả chi phí","Khac":"Hóa đơn bất hợp pháp có thể bị xử lý trốn thuế"},"lienKet":["R04","R05","R06","R08","R09","R11"],"nguyenNhanBS":["Thuế đầu vào dự án đầu tư khai trên tờ khai riêng (02/GTGT)","Hóa đơn của người bán đã bỏ địa chỉ kinh doanh, ngừng hoạt động: đã loại trên tờ khai nhưng chưa loại trên sổ"],"hoSoBS":["Kết quả tra cứu tình trạng MST người bán tại thời điểm lập hóa đơn"],"luuY":"Ngưỡng chứng từ thanh toán không dùng tiền mặt: 20 triệu đồng đến 30/6/2025, 05 triệu đồng (giá đã có thuế) từ 01/7/2025."},"R04":{"muc":"NT","yNghia":"Khi DN vừa có DT chịu thuế vừa có DT không chịu thuế GTGT, thuế đầu vào dùng chung chỉ được khấu trừ theo tỷ lệ DT chịu thuế trên tổng DT. Nếu [26] > 0 mà [25] = [24] thì DN đã khấu trừ 100%, chưa phân bổ.","cachDanhGia":"[26] = 0: không áp dụng. [26] > 0 và [25] = [24]: mức cao; thuế ước tính phải loại ≈ thuế đầu vào dùng chung × [26] / [34]. [26] > 0 và [25] < [24]: kiểm tra tỷ lệ phân bổ và việc quyết toán phân bổ cuối năm.","ruiRo":{"GTGT":"Loại thuế đầu vào khấu trừ vượt tỷ lệ","TNDN":"Phần không được khấu trừ do phân bổ được tính vào chi phí (giảm rủi ro TNDN)","Khac":""},"lienKet":["R01","R03"],"nguyenNhanBS":["Phân bổ tạm tính theo tháng, quyết toán lại cuối năm qua [37]/[38]"],"hoSoBS":["Bảng tách thuế đầu vào: dùng riêng chịu thuế / dùng riêng không chịu thuế / dùng chung"],"luuY":""},"R05":{"muc":"TY","yNghia":"Số thuế còn được khấu trừ mang sang đầu năm phải bằng số dư 133 đầu năm, và [22] kỳ đầu năm phải bằng [43] kỳ cuối năm trước. Chuỗi chuyển kỳ không được đứt.","cachDanhGia":"CL > 0: tờ khai mang sang nhiều hơn sổ, nghi khấu trừ khống chuyển kỳ. CL < 0: 133 trên sổ còn treo thuế không đủ điều kiện, hoặc số đã đề nghị hoàn chưa nhận tiền.","ruiRo":{"GTGT":"Khấu trừ hoặc hoàn thuế sai","TNDN":"","Khac":"Kiểm tra liên tục với R06 của năm trước"},"lienKet":["R06","R09"],"nguyenNhanBS":["Khai bổ sung kỳ trước làm giảm [43] nhưng sổ chưa điều chỉnh"],"hoSoBS":[],"luuY":"Năm đầu tiên rà soát: lấy dư đầu kỳ từ CĐPS, không để 0."},"R06":{"muc":"TY","yNghia":"Số thuế còn được khấu trừ cuối năm trên tờ khai phải bằng số dư 133. Lệch là dấu hiệu khấu trừ chuyển kỳ khống hoặc sổ sách phản ánh sai.","cachDanhGia":"CL > 0: mức cao với DN còn khấu trừ lớn nhiều kỳ hoặc có đề nghị hoàn. CL < 0: thuế đầu vào chưa kê khai hoặc không đủ điều kiện. Khi có đề nghị hoàn chưa nhận tiền: so [43] + [42] chưa hoàn với dư 133.","ruiRo":{"GTGT":"Giảm số còn được khấu trừ, thu hồi hoàn","TNDN":"","Khac":"Còn khấu trừ lớn kéo dài nhiều kỳ là tiêu chí chọn kiểm tra"},"lienKet":["R05","R09"],"nguyenNhanBS":["Bù trừ thuế đầu vào dự án đầu tư [40b]"],"hoSoBS":["Bảng theo dõi [43] từng kỳ trong năm"],"luuY":""},"R07":{"muc":"TY","yNghia":"Mọi doanh thu bán chịu phải đi qua Nợ 131. So sánh cho biết có doanh thu kê khai mà không có công nợ (bán thu tiền ngay hoặc hóa đơn không có giao dịch thật), hay có công nợ phát sinh mà không thành doanh thu (sót DT, treo 338/3387).","cachDanhGia":"CL > 0: phần DT không qua 131 phải chứng minh thu tiền ngay (đối chiếu 111/112). CL < 0: phân tích đối ứng Có của Nợ 131 (711, 515, 3387, 338, 413); nghi sót DT.","ruiRo":{"GTGT":"Sót DT, thuế đầu ra (CL < 0)","TNDN":"Sót DT (CL < 0); hóa đơn bán ra khống (CL > 0, không có dòng tiền)","Khac":""},"lienKet":["R01","R02","R10","R23","R27"],"nguyenNhanBS":["Chênh lệch tỷ giá ghi Nợ 131/Có 413"],"hoSoBS":[],"luuY":"Mẫu CQT 2018 lấy SL1 = [34] + [35] (tờ khai), mẫu 2023–2025 lại lấy số sổ sách. App dùng số tờ khai, đúng mục đích đối chiếu tờ khai ↔ công nợ."},"R08":{"muc":"TY","yNghia":"Mua chịu phải qua Có 331. Tờ khai mua vào lớn hơn Có 331 mà không có thanh toán ngay tương ứng là dấu hiệu kê khai hóa đơn không có giao dịch thật. Có 331 lớn hơn tờ khai là dấu hiệu mua hàng không có hóa đơn hoặc mua của cá nhân.","cachDanhGia":"CL > 0: mức cao nếu không chứng minh được thanh toán ngay (111/112/141). CL < 0: kiểm tra mua không hóa đơn, nhập khẩu, mua của hộ/cá nhân (bảng kê 01/TNDN).","ruiRo":{"GTGT":"Loại khấu trừ hóa đơn không có thật","TNDN":"Loại chi phí không có hóa đơn, chứng từ hợp lệ","Khac":"Nghi vấn sử dụng hóa đơn bất hợp pháp"},"lienKet":["R03","R11","R12"],"nguyenNhanBS":["Thuế GTGT hàng nhập khẩu nộp ở khâu hải quan (Có 33312), không qua 331","Điện, nước, viễn thông thanh toán thẳng qua 112"],"hoSoBS":["Danh sách nhà cung cấp lớn kèm tình trạng MST"],"luuY":""},"R09":{"muc":"TY","yNghia":"PS Có 133 gồm: (1) khấu trừ với đầu ra, (2) được hoàn, (3) loại khỏi khấu trừ đưa vào chi phí, (4) hàng mua trả lại. Sau khi trừ (1), phần còn lại phải giải thích được bằng (2) + (3) + (4). Tiêu chí cho biết DN ghi giảm 133 đúng số hoàn chưa và đã đưa thuế không được khấu trừ vào chi phí như thế nào.","cachDanhGia":"CL > 0: có khoản ghi giảm 133 ngoài hoàn thuế, kiểm tra đối ứng. CL < 0: nhận tiền hoàn nhưng không ghi giảm 133 (ghi 711/338), 133 bị treo và có thể bị khấu trừ hai lần.","ruiRo":{"GTGT":"Khấu trừ, hoàn trùng; thu hồi hoàn","TNDN":"Thuế GTGT không được khấu trừ do không thanh toán qua ngân hàng thì cũng không được tính vào chi phí","Khac":"Thu hồi hoàn và chậm nộp từ ngày nhận tiền hoàn"},"lienKet":["R03","R05","R06","R17"],"nguyenNhanBS":["Đề nghị hoàn năm N, nhận tiền năm N+1"],"hoSoBS":[],"luuY":""},"R10":{"muc":"TY","yNghia":"Ước tính tiền phải thu được từ doanh thu đã kê khai rồi so với tiền thu thực tế trên LCTT. Tiền thu lớn hơn số suy ra: có tiền vào mà không có doanh thu tương ứng (bán không xuất hóa đơn). Tiền thu nhỏ hơn: doanh thu không có dòng tiền (hóa đơn khống, bù trừ, xóa nợ).","cachDanhGia":"Chỉ có ý nghĩa với LCTT lập theo phương pháp trực tiếp; DN lập gián tiếp thì đối chiếu sao kê ngân hàng thay thế. CL < 0: rà sao kê, tìm khoản thu không phải DT. CL > 0: kiểm tra bù trừ công nợ, xóa nợ.","ruiRo":{"GTGT":"Sót DT bán ra không xuất hóa đơn","TNDN":"Sót DT","Khac":"Chất lượng lập LCTT"},"lienKet":["R01","R07","R23","R27","R34"],"nguyenNhanBS":["Xóa nợ phải thu khó đòi","Tiền thu thanh lý TSCĐ phân loại sai vào mã 01 (đúng là mã 22)"],"hoSoBS":[],"luuY":"Số dư đầu/cuối 131, 312 phải lấy đúng năm. File mẫu năm 2018–2019 nhập cứng số dư, năm 2019 vẫn dùng số dư 2018."},"R11":{"muc":"TY","yNghia":"Ước tính tiền phải chi cho HHDV mua vào có hóa đơn rồi so với tiền thực chi. Mua vào có hóa đơn lớn mà tiền chi thấp, công nợ không tăng: hóa đơn đầu vào có thể không có giao dịch thật. Tiền chi lớn hơn: có mua hàng không hóa đơn, hoặc khoản chi khác phân loại sai.","cachDanhGia":"CL > 0: mức cao, kiểm tra từng nhà cung cấp lớn (chứng từ thanh toán, tình trạng MST). CL < 0: kiểm tra mua không hóa đơn, mua của cá nhân.","ruiRo":{"GTGT":"Loại khấu trừ hóa đơn không thanh toán","TNDN":"Loại chi phí","Khac":"Dấu hiệu mua bán hóa đơn"},"lienKet":["R08","R12","R38"],"nguyenNhanBS":["[23] gồm cả mua TSCĐ, XDCB nhưng tiền chi nằm ở LCTT mã 21"],"hoSoBS":[],"luuY":"Năm có đầu tư TSCĐ: trừ phần mua TSCĐ (thuế đầu vào 1332 và giá trị tương ứng) khỏi SL1 trước khi kết luận, nếu không chênh lệch bị phóng đại."},"R12":{"muc":"TY","yNghia":"Giá vốn phải hình thành từ hàng tồn kho, chi phí dở dang xuất ra. Nợ 632 lớn hơn xuất kho: có chi phí đưa thẳng vào giá vốn không qua kho (cần chứng minh) hoặc ghi khống giá vốn. Xuất kho lớn hơn giá vốn: hàng xuất cho mục đích khác (biếu tặng, khuyến mại, tiêu dùng nội bộ, góp vốn) phải kê khai GTGT đầu ra.","cachDanhGia":"CL < 0: liệt kê bút toán Nợ 632 không đối ứng kho. CL > 0: kiểm tra Có 155/156 đối ứng TK khác 632 (641, 642, 811, 241, 222).","ruiRo":{"GTGT":"Hàng biếu tặng, tiêu dùng nội bộ chưa kê khai thuế đầu ra","TNDN":"Giá vốn không có chứng từ, vượt định mức; xuất âm kho","Khac":""},"lienKet":["R01","R02","R08","R32"],"nguyenNhanBS":["DN dịch vụ (không có kho): giá vốn hình thành từ 154 (lương, BHXH, khấu hao, thuê ngoài)","Khấu hao, chi phí BĐS đầu tư ghi 632"],"hoSoBS":["Bảng tính giá thành, định mức nguyên vật liệu"],"luuY":"Cộng tổng PS Có 154 + 155 + 156 sẽ tính trùng bút toán 154 → 155 (nhập kho thành phẩm). Đọc chênh lệch sau khi trừ PS Nợ 155 đối ứng Có 154, hoặc dùng phát sinh đối ứng Nợ 632 nếu có sổ chi tiết."},"R13":{"muc":"NHO","yNghia":"Giảm trừ DT làm giảm cả DT tính thuế TNDN và (nếu có hóa đơn điều chỉnh) thuế GTGT đầu ra. CQT kiểm tra: CKTM, giảm giá phải thể hiện trên hóa đơn; hàng bán trả lại phải có hóa đơn điều chỉnh theo NĐ 123/2020 sửa đổi bởi NĐ 70/2025.","cachDanhGia":"[06] = 0: không rủi ro. [06] > 0: kiểm tra hồ sơ. Tỷ lệ giảm trừ / DT tăng đột biến so năm trước thì nâng mức.","ruiRo":{"GTGT":"Giảm thuế đầu ra không có hóa đơn điều chỉnh hợp lệ","TNDN":"Giảm DT không đủ hồ sơ","Khac":""},"lienKet":["R01"],"nguyenNhanBS":[],"hoSoBS":[],"luuY":"Mẫu CQT ghi '[03]' theo mẫu cũ; theo PL 03-1A TT 80 là [06]."},"R14":{"muc":"TY","yNghia":"Thu nhập khác là vùng rủi ro vì: (1) nhiều khoản chịu GTGT (thanh lý TSCĐ, bán phế liệu) phải lập hóa đơn; (2) thu nhập khác không được hưởng ưu đãi TNDN, phải tách khỏi thu nhập ưu đãi; (3) DT hoạt động chính có thể bị hạch toán sai vào 711.","cachDanhGia":"Thu nhập khác = 0 nhưng TSCĐ giảm trong năm: kiểm tra thanh lý. Có thu nhập khác: phân loại từng khoản chịu GTGT / không chịu / không phải kê khai tính nộp; DN có ưu đãi thì kiểm tra đã tách khỏi phần ưu đãi (R21).","ruiRo":{"GTGT":"Sót thuế đầu ra khoản thanh lý, phế liệu, dịch vụ hỗ trợ","TNDN":"Áp sai ưu đãi cho thu nhập khác","Khac":""},"lienKet":["R01","R21"],"nguyenNhanBS":["Bán phế liệu, phế phẩm"],"hoSoBS":[],"luuY":"Mẫu 2018–2020 ghi '[16]' theo mẫu cũ; theo PL 03-1A TT 80 là [19]."},"R15":{"muc":"TY","yNghia":"Doanh thu đã đủ điều kiện tính thuế theo luật thuế (đã lập hóa đơn, đã hoàn thành dịch vụ) nhưng kế toán chưa ghi nhận. Khoản tăng năm N sẽ được giảm qua [B9] ở năm kế toán ghi nhận; B2 và B9 đi thành cặp qua các năm.","cachDanhGia":"B2 > 0: ghi sổ theo dõi lũy kế để kiểm tra R16 năm sau. B2 = 0 nhưng R01 có DT GTGT > DT kế toán, hoặc dư 3387/312 lớn: nghi chưa điều chỉnh tăng.","ruiRo":{"GTGT":"","TNDN":"Sót DT tính thuế nếu không điều chỉnh","Khac":""},"lienKet":["R01","R16","R27","R30"],"nguyenNhanBS":["Cho thuê tài sản thu trước nhiều năm, DN chọn kê khai một lần","DT tính theo giá giao dịch độc lập (giao dịch liên kết)"],"hoSoBS":["Bảng theo dõi lũy kế B2 – B9 theo từng hợp đồng"],"luuY":""},"R16":{"muc":"TY","yNghia":"Khoản giảm thu nhập: DT kế toán năm nay ghi nhận nhưng đã tính thuế năm trước. CQT chỉ chấp nhận khi chứng minh được đã kê khai tăng B2 năm trước.","cachDanhGia":"B9 > 0 mà không có B2 tương ứng các năm trước: mức cao, giảm thu nhập không có căn cứ. Kiểm tra B9 năm N ≤ Σ B2 các năm trước − Σ B9 đã dùng.","ruiRo":{"GTGT":"","TNDN":"Truy thu nếu không chứng minh được","Khac":""},"lienKet":["R01","R15"],"nguyenNhanBS":[],"hoSoBS":["Bảng đối chiếu theo từng hợp đồng giữa B2 năm trước và B9 năm nay"],"luuY":""},"R17":{"muc":"TY","yNghia":"Cho biết DN đã tự loại các chi phí không đủ điều kiện chưa. CQT so B4 với các khoản chắc chắn không được trừ trên BCTC: tiền phạt vi phạm hành chính, tiền chậm nộp, chi phí thuế TNDN, khấu hao phần nguyên giá ô tô vượt 1,6 tỷ, lãi vay tương ứng vốn điều lệ còn thiếu, lãi vay vượt 30% EBITDA (giao dịch liên kết), chi tiền mặt từ ngưỡng, chi không có hóa đơn.","cachDanhGia":"B4 = 0 nhưng BCTC có 811, lãi vay lớn, ô tô giá trị lớn: nâng mức. B4 nhỏ hơn tổng khoản không được trừ app phát hiện: phần thiếu là thu nhập chịu thuế bị khai thiếu.","ruiRo":{"GTGT":"","TNDN":"Truy thu trên phần chi phí không được trừ chưa loại","Khac":"Phạt 20% và chậm nộp"},"lienKet":["R09","R28","R29","R32","R36"],"nguyenNhanBS":[],"hoSoBS":["Phụ lục giao dịch liên kết (mẫu 01 NĐ 132) và bảng tính lãi vay theo EBITDA (nếu có)"],"luuY":"Ngưỡng chi phí tiền mặt TNDN: 20 triệu đến 14/12/2025, 05 triệu từ 15/12/2025 (NĐ 320/2025) — cần đối chiếu."},"R18":{"muc":"NHO","yNghia":"Dùng cho các khoản tăng thu nhập ngoài B2–B6. Điển hình là lỗ chênh lệch tỷ giá do đánh giá lại cuối kỳ khoản tiền và nợ phải thu gốc ngoại tệ (không được tính vào chi phí), chi phí trích trước không thực chi.","cachDanhGia":"Có số dư ngoại tệ cuối kỳ mà B7 = 0 và B12 = 0: xem R22. B7 > 0: kiểm tra nội dung đúng bản chất.","ruiRo":{"GTGT":"","TNDN":"Sót điều chỉnh tăng","Khac":""},"lienKet":["R19","R22"],"nguyenNhanBS":["Hoàn nhập chi phí trích trước không chi"],"hoSoBS":[],"luuY":""},"R19":{"muc":"TY","yNghia":"Khoản làm giảm thu nhập chịu thuế nên CQT kiểm tra kỹ. Hợp lệ khi: lãi chênh lệch tỷ giá đánh giá lại cuối kỳ khoản tiền và phải thu gốc ngoại tệ, chi phí năm trước đã loại nay đủ điều kiện, cổ tức đã chịu thuế.","cachDanhGia":"B12 = 0: đạt. B12 > 0 không có bảng chi tiết, chứng từ: mức cao. B12 lớn so với lợi nhuận trước thuế: nâng mức.","ruiRo":{"GTGT":"","TNDN":"Giảm thu nhập không có căn cứ thì bị truy thu","Khac":""},"lienKet":["R18","R22"],"nguyenNhanBS":[],"hoSoBS":["Bảng chi tiết từng khoản điều chỉnh giảm kèm chứng từ gốc"],"luuY":"Mẫu CQT ghi 'B11'; theo 03/TNDN TT 80, B11 là lãi vay không được trừ kỳ trước chuyển sang, điều chỉnh giảm khác là B12. App kiểm tra cả hai."},"R20":{"muc":"TY","yNghia":"Chuyển lỗ làm giảm thu nhập tính thuế. Sai thường gặp: chuyển quá 5 năm; dùng số lỗ trên tờ khai khi CQT đã kiểm tra và giảm lỗ; không chuyển theo thứ tự năm; bù trừ lỗ của hoạt động không được phép bù trừ.","cachDanhGia":"C3 > 0: đọc PL 03-2A, kiểm tra thời hạn 5 năm và số lỗ đã được CQT xác nhận. Lỗ năm nào bị kết luận thanh tra điều chỉnh thì dùng số sau kết luận.","ruiRo":{"GTGT":"","TNDN":"Truy thu do chuyển lỗ sai","Khac":"Lỗ nhiều năm liên tục là tiêu chí chọn kiểm tra"},"lienKet":["R39"],"nguyenNhanBS":[],"hoSoBS":[],"luuY":"Quy định bù trừ lỗ chuyển nhượng BĐS với SXKD theo Luật TNDN 67/2025 — cần đối chiếu."},"R21":{"muc":"TY","yNghia":"Ưu đãi chỉ áp cho thu nhập từ hoạt động/dự án đủ điều kiện (địa bàn, ngành nghề, dự án đầu tư mới, thời gian ưu đãi). Thu nhập khác, thu nhập tài chính, thu nhập ngoài dự án phải tách riêng và tính thuế suất phổ thông.","cachDanhGia":"Có miễn giảm: kiểm tra còn trong thời gian ưu đãi; đã tách thu nhập không ưu đãi (R14, R37); có hạch toán riêng; đủ điều kiện về vốn, lao động, doanh thu.","ruiRo":{"GTGT":"","TNDN":"Thu hồi số thuế miễn giảm sai","Khac":""},"lienKet":["R14","R37"],"nguyenNhanBS":[],"hoSoBS":[],"luuY":"Thuế suất 15%/17%/20% theo Luật 67/2025 là thuế suất, không phải miễn giảm, nên không xét ở tiêu chí này."},"R22":{"muc":"NHO","yNghia":"Chênh lệch tỷ giá đánh giá lại cuối kỳ các khoản mục tiền và nợ phải thu gốc ngoại tệ: lãi thì không tính vào thu nhập (điều chỉnh giảm), lỗ thì không được trừ (điều chỉnh tăng B7). DN có ngoại tệ mà không điều chỉnh gì là dấu hiệu chưa xử lý.","cachDanhGia":"Không có ngoại tệ: không áp dụng. Có ngoại tệ, B7 = B12 = 0: mức thấp, nâng lên nếu số đánh giá lại trên 515/635 lớn.","ruiRo":{"GTGT":"","TNDN":"Sai thu nhập chịu thuế do chênh lệch tỷ giá","Khac":""},"lienKet":["R18","R19","R37"],"nguyenNhanBS":["Đánh giá lại chỉ phát sinh trên nợ phải trả (được tính vào thu nhập/chi phí, không cần điều chỉnh)"],"hoSoBS":[],"luuY":""},"R23":{"muc":"TY","yNghia":"Phải thu lớn, tăng nhanh hơn DT hoặc kéo dài là dấu hiệu: DT không có thật hoặc không thu được; bán cho bên liên quan nhưng không thu (cho vay trá hình không lãi); khách hàng đã ngừng hoạt động; trích dự phòng sai.","cachDanhGia":"Số ngày thu tiền (dư 131 bình quân / DT × 365) tăng mạnh so năm trước, hoặc phải thu > 50% DT năm: nâng mức. Khách nợ lớn là DN ngừng hoạt động, bỏ địa chỉ: mức cao. Lập bảng theo khách hàng: tên, ngày ký hợp đồng, ngày xuất hóa đơn, số tiền, tuổi nợ.","ruiRo":{"GTGT":"Hóa đơn bán ra không có giao dịch thật","TNDN":"DT khống, giao dịch bên liên quan, dự phòng sai","Khac":"Giao dịch liên kết (NĐ 132/2020)"},"lienKet":["R07","R10","R25"],"nguyenNhanBS":[],"hoSoBS":["Bảng tuổi nợ theo khách hàng (ngày ký hợp đồng, ngày xuất hóa đơn, số tiền)"],"luuY":""},"R24":{"muc":"TY","yNghia":"Vùng rủi ro 'tiền ra khỏi DN không qua chi phí': cho cá nhân, thành viên, ban giám đốc mượn không lãi; tạm ứng lâu không hoàn; rút vốn trá hình. Nếu DN đồng thời đi vay trả lãi thì CQT có thể loại phần lãi vay tương ứng; khoản cá nhân sử dụng có thể bị xem là thu nhập TNCN.","cachDanhGia":"Có số dư với cá nhân, ban giám đốc, bên liên quan: nâng mức. Tạm ứng tồn quá 1 năm: nâng mức. DN có vay nợ (635 > 0) và có phải thu khác không lãi: mức cao. Lập bảng tạm ứng theo nhân viên.","ruiRo":{"GTGT":"","TNDN":"Loại lãi vay tương ứng; chi phí đã phát sinh chưa ghi nhận","Khac":"TNCN đối với cá nhân sử dụng tiền DN"},"lienKet":["R35","R36"],"nguyenNhanBS":[],"hoSoBS":["Hợp đồng mượn tiền (nếu có), giấy đề nghị tạm ứng và thanh toán tạm ứng"],"luuY":""},"R25":{"muc":"TY","yNghia":"Dự phòng làm tăng chi phí được trừ. Chỉ được trừ khi đủ điều kiện TT 48/2019 (sửa đổi bởi TT 24/2022): có chứng từ gốc, đối chiếu nợ; quá hạn từ 6 tháng đến dưới 1 năm trích 30%, 1–2 năm 50%, 2–3 năm 70%, từ 3 năm 100%; hoặc khách nợ phá sản, giải thể, mất tích, bỏ trốn.","cachDanhGia":"Có số dư: kiểm tra từng khoản theo tuổi nợ × tỷ lệ; trích vượt thì đưa phần vượt vào B4 (R17). Nợ của bên liên quan, nợ không có đối chiếu: mức cao.","ruiRo":{"GTGT":"","TNDN":"Loại chi phí dự phòng trích sai","Khac":""},"lienKet":["R23","R32","R17"],"nguyenNhanBS":[],"hoSoBS":[],"luuY":""},"R26":{"muc":"TY","yNghia":"XDCB dở dang kéo dài là dấu hiệu: công trình đã hoàn thành, đưa vào sử dụng nhưng chưa ghi tăng TSCĐ; chi phí không liên quan bị treo; thuế đầu vào dự án đã đề nghị hoàn. Ngược lại, chi phí XDCB đưa thẳng vào chi phí SXKD làm giảm thu nhập.","cachDanhGia":"Số dư không đổi hoặc tăng liên tục từ 2 năm mà không tăng TSCĐ: nâng mức. Có đề nghị hoàn thuế dự án: kiểm tra hồ sơ dự án. Liên hệ R38.","ruiRo":{"GTGT":"Hoàn thuế dự án sai","TNDN":"Khấu hao, vốn hóa lãi vay sai","Khac":""},"lienKet":["R38","R03","R06"],"nguyenNhanBS":[],"hoSoBS":[],"luuY":""},"R27":{"muc":"NT","yNghia":"Dư Có 131 lớn là rủi ro hàng đầu về thời điểm lập hóa đơn: hàng đã giao, dịch vụ đã hoàn thành nhưng chưa xuất hóa đơn. Với dịch vụ, thời điểm lập hóa đơn là khi thu tiền nếu thu trước (trừ đặt cọc); với xây dựng, BĐS thu theo tiến độ phải lập hóa đơn khi thu tiền.","cachDanhGia":"Có số dư: lập bảng khách hàng, dư Có cuối kỳ, ngày giao hàng/nghiệm thu, số và ngày hóa đơn xuất năm sau. Khoản ứng trước của dịch vụ đã thu tiền mà chưa có hóa đơn: mức cao.","ruiRo":{"GTGT":"Chậm kê khai thuế đầu ra","TNDN":"Sót DT","Khac":"Phạt lập hóa đơn sai thời điểm"},"lienKet":["R01","R10","R15","R30"],"nguyenNhanBS":[],"hoSoBS":[],"luuY":""},"R28":{"muc":"TY","yNghia":"Tiền lương đã hạch toán chi phí nhưng thực tế không chi trả hoặc không có chứng từ thanh toán thì không được trừ. Lương trích năm N phải chi trước thời hạn nộp hồ sơ quyết toán TNDN mới được tính vào chi phí năm N. Đồng thời liên quan khấu trừ TNCN theo thời điểm chi trả.","cachDanhGia":"Dư Có 334 khoảng 1 tháng lương và có chứng từ chi trước hạn quyết toán: đạt. Dư lớn hơn nhiều tháng lương hoặc không có chứng từ chi: nâng mức, đưa phần không chi vào B4.","ruiRo":{"GTGT":"","TNDN":"Loại chi phí lương không chi trả","Khac":"TNCN, BHXH tính theo quỹ lương"},"lienKet":["R17","R29"],"nguyenNhanBS":[],"hoSoBS":["Chứng từ chuyển khoản lương kèm ngày chi trả thực tế"],"luuY":"Thời hạn chi lương trích trước theo NĐ 320/2025 — cần đối chiếu."},"R29":{"muc":"TY","yNghia":"Chi phí trích trước chỉ được trừ khi đúng kỳ hạn, có căn cứ, và khi thực chi phải có hóa đơn, chứng từ; nếu thực chi thấp hơn số trích phải ghi giảm chi phí. Trích trước để giảm thuế là rủi ro phổ biến.","cachDanhGia":"Có số dư: liệt kê từng khoản (nội dung, căn cứ, ngày thực chi, hóa đơn). Khoản không có hóa đơn đến thời điểm quyết toán: đưa vào B4. Dư 335 tồn qua nhiều năm: mức cao.","ruiRo":{"GTGT":"","TNDN":"Loại chi phí trích trước không đủ điều kiện","Khac":""},"lienKet":["R17","R28"],"nguyenNhanBS":["Chi phí công trình đã nghiệm thu chưa có hóa đơn của thầu phụ"],"hoSoBS":[],"luuY":""},"R30":{"muc":"TY","yNghia":"DT nhận trước (cho thuê nhiều kỳ, lãi trả chậm, khách hàng thân thiết) được phân bổ nhiều kỳ. Về thuế: GTGT kê khai khi lập hóa đơn hoặc thu tiền; TNDN cho thuê thu trước nhiều năm được chọn phân bổ hoặc tính một lần. Số dư lớn, không có B2 và không có hóa đơn đã khai GTGT là dấu hiệu sót DT.","cachDanhGia":"Có số dư: đối chiếu hóa đơn đã lập (R01). Khoản thực chất là DT đã hoàn thành nhưng treo 3387: mức cao.","ruiRo":{"GTGT":"Chưa kê khai thuế đầu ra khoản thu trước","TNDN":"Sót DT","Khac":""},"lienKet":["R01","R15","R27"],"nguyenNhanBS":["Bán hàng trả góp, trả chậm (lãi trả chậm)"],"hoSoBS":[],"luuY":"TT 133 không có chỉ tiêu riêng; đọc dư Có 3387 trên CĐPS."},"R31":{"muc":"NHO","yNghia":"Phát sinh khi có chênh lệch tạm thời chịu thuế giữa kế toán và thuế (khấu hao, DT/chi phí ghi nhận khác kỳ). Có số dư chứng tỏ DN biết có khác biệt kế toán – thuế; cần kiểm tra các khác biệt đó đã phản ánh trên quyết toán, và chi phí thuế TNDN hoãn lại (8212) không được tính vào chi phí được trừ.","cachDanhGia":"Có số dư: yêu cầu bảng tính chênh lệch tạm thời; đối chiếu với B2/B9, B4, B7/B12. Không có số dư: không áp dụng (DN nhỏ thường không áp dụng VAS 17).","ruiRo":{"GTGT":"","TNDN":"Điều chỉnh thu nhập chịu thuế sai","Khac":""},"lienKet":["R15","R16","R17"],"nguyenNhanBS":[],"hoSoBS":[],"luuY":""},"R32":{"muc":"TY","yNghia":"Dự phòng chỉ được trừ đúng đối tượng, điều kiện, mức trích tại TT 48/2019 (sửa đổi bởi TT 24/2022): giảm giá HTK (có hồ sơ giá thị trường), tổn thất đầu tư, nợ khó đòi, bảo hành sản phẩm/hàng hóa/công trình xây dựng. Dự phòng phải trả khác (tái cơ cấu, hợp đồng rủi ro lớn) không được trừ. Hoàn nhập phải ghi giảm chi phí.","cachDanhGia":"Có số dư hoặc biến động: kiểm tra hồ sơ từng loại. Dự phòng không thuộc đối tượng TT 48: đưa vào B4. Dự phòng bảo hành vượt mức: nâng mức.","ruiRo":{"GTGT":"","TNDN":"Loại chi phí dự phòng sai","Khac":""},"lienKet":["R25","R12","R17"],"nguyenNhanBS":["Dự phòng tái cơ cấu, hợp đồng rủi ro lớn (không được trừ)"],"hoSoBS":[],"luuY":""},"R33":{"muc":"TY","yNghia":"Quỹ KH&CN được trích trước khi tính thuế (C5, giảm thu nhập tính thuế). Không sử dụng, sử dụng sai mục đích hoặc không đủ tỷ lệ tối thiểu trong thời hạn thì phải nộp lại thuế TNDN trên phần quỹ đó cộng tiền lãi.","cachDanhGia":"C5 > 0 hoặc có dư quỹ: kiểm tra mức trích, quyết định trích, báo cáo trích lập – sử dụng quỹ (03-6/TNDN). Quỹ quá thời hạn chưa dùng: mức cao.","ruiRo":{"GTGT":"","TNDN":"Truy thu thuế và lãi trên quỹ không sử dụng đúng","Khac":""},"lienKet":["R21"],"nguyenNhanBS":[],"hoSoBS":["Quyết định trích quỹ của DN"],"luuY":"Mức trích tối đa và thời hạn sử dụng theo Luật TNDN 67/2025 — cần đối chiếu (luật cũ: tối đa 10% thu nhập tính thuế, sử dụng từ 70% trong 5 năm)."},"R34":{"muc":"TY","yNghia":"Tiền vào không phải từ bán hàng: thu hồi hoặc nhận ký quỹ, bồi thường, thưởng, hỗ trợ, thu hồi tạm ứng. Khoản lớn bất thường có thể là tiền bán hàng hạch toán qua 338/711 để né DT, hoặc tiền mượn của cá nhân lẽ ra thuộc hoạt động tài chính (mã 33).","cachDanhGia":"Lớn so với tiền thu bán hàng hoặc tăng đột biến: lập bảng phân loại theo đối ứng tài khoản.","ruiRo":{"GTGT":"Sót DT","TNDN":"Sót DT, thu nhập khác","Khac":"Phân loại LCTT sai"},"lienKet":["R10","R14","R24"],"nguyenNhanBS":["Nhận tiền mượn của cá nhân (đúng ra thuộc mã 33)"],"hoSoBS":[],"luuY":""},"R35":{"muc":"NT","yNghia":"Tiền ra không phải trả nhà cung cấp, lương, lãi vay, thuế TNDN: ký quỹ, tạm ứng, cho cá nhân mượn, chi quỹ khen thưởng phúc lợi, chi phạt. Khoản lớn là dấu hiệu tiền đi ra cho cá nhân, bên liên quan (cho vay trá hình, rút vốn) hoặc chi phí không có hóa đơn.","cachDanhGia":"Lớn so với tiền chi nhà cung cấp hoặc so DT: mức cao, lập bảng chi tiết theo đối tượng nhận tiền. Ví dụ file mẫu 2018: 11,76 tỷ ≈ 32% DT, rất cao.","ruiRo":{"GTGT":"","TNDN":"Chi phí không chứng từ; loại lãi vay khi cho mượn không lãi","Khac":"TNCN; giao dịch liên kết"},"lienKet":["R24","R36"],"nguyenNhanBS":["Chi quỹ khen thưởng, phúc lợi; chi cho cá nhân mượn"],"hoSoBS":[],"luuY":""},"R36":{"muc":"TY","yNghia":"DN cho vay phải ghi nhận thu nhập lãi. Cho bên liên quan vay không lãi hoặc lãi thấp: CQT ấn định theo giá giao dịch độc lập (NĐ 132/2020). DN vừa đi vay trả lãi vừa cho vay không lãi: lãi vay tương ứng có nguy cơ bị loại. Cho cá nhân vay cần xem bản chất (rút vốn).","cachDanhGia":"Có cho vay mà R37 = 0: mức cao (cho vay không thu lãi). Lập bảng: ngày, bên vay, số tiền, tăng/giảm, dư nợ, lãi.","ruiRo":{"GTGT":"","TNDN":"Bỏ sót thu nhập lãi; loại lãi vay","Khac":"Giao dịch liên kết"},"lienKet":["R24","R35","R37"],"nguyenNhanBS":[],"hoSoBS":["Sổ chi tiết 128/1283/1388 theo bên vay"],"luuY":""},"R37":{"muc":"NHO","yNghia":"Kiểm tra thu nhập tài chính ghi nhận đầy đủ. Cổ tức, lợi nhuận được chia từ DN trong nước đã nộp TNDN là thu nhập không chịu thuế/miễn thuế. Thu nhập lãi không được hưởng ưu đãi TNDN. Có cho vay (R36) mà không có thu lãi là rủi ro.","cachDanhGia":"Tiền lãi, cổ tức thực thu khác lãi, cổ tức trên 515 (đã tính biến động lãi phải thu): nâng mức. Cổ tức có trong 515 nhưng chưa điều chỉnh giảm: DN đang nộp thừa.","ruiRo":{"GTGT":"","TNDN":"Áp ưu đãi cho thu nhập lãi; thiếu thu nhập lãi","Khac":""},"lienKet":["R21","R36"],"nguyenNhanBS":["Lãi dự thu chưa thu tiền"],"hoSoBS":[],"luuY":"Theo TT 133, thu lãi và cổ tức là mã 25 trên LCTT."},"R38":{"muc":"TY","yNghia":"Đầu tư TSCĐ ảnh hưởng thuế qua: khấu trừ, hoàn thuế đầu vào TSCĐ (1332); khấu hao (ô tô dưới 9 chỗ phần nguyên giá vượt 1,6 tỷ không được trừ); TSCĐ không phục vụ SXKD; TSCĐ mua của cá nhân không hóa đơn; khấu hao khi chưa đưa vào sử dụng.","cachDanhGia":"Có tiền chi mua TSCĐ mà không tăng TSCĐ, XDCB: nâng mức. Tăng TSCĐ có ô tô, tài sản giá trị lớn: kiểm tra khấu hao phần vượt và mục đích sử dụng.","ruiRo":{"GTGT":"Khấu trừ, hoàn thuế đầu vào TSCĐ không phục vụ SXKD chịu thuế","TNDN":"Khấu hao không được trừ","Khac":""},"lienKet":["R11","R26","R03"],"nguyenNhanBS":["Trả trước cho nhà thầu XDCB; thanh toán nợ mua TSCĐ năm trước"],"hoSoBS":[],"luuY":"Mã 21 giống nhau ở LCTT trực tiếp và gián tiếp, nên tiêu chí áp dụng cho cả hai."},"R39":{"muc":"NT","yNghia":"Ý kiến không phải chấp nhận toàn phần cho biết kiểm toán viên không đủ bằng chứng hoặc phát hiện sai sót trọng yếu; đây là điểm vào trực tiếp cho CQT. Vấn đề ngoại trừ thường gặp: không chứng kiến kiểm kê HTK, không xác nhận được công nợ, dự phòng, giá vốn, chi phí trích trước, TSCĐ.","cachDanhGia":"Ngoại trừ: gắn từng vấn đề ngoại trừ với tiêu chí liên quan (HTK → R12; công nợ → R23, R27; dự phòng → R25, R32; chi phí trích trước → R29). Từ chối hoặc trái ngược: mức cao. BCTC không kiểm toán: không áp dụng.","ruiRo":{"GTGT":"Theo vấn đề ngoại trừ","TNDN":"Theo vấn đề ngoại trừ","Khac":"Tiêu chí chọn hồ sơ thanh tra, kiểm tra"},"lienKet":["R12","R23","R25","R27","R29","R32"],"nguyenNhanBS":[],"hoSoBS":[],"luuY":""}}
const MUC = {"NT":"Nghiêm trọng","TY":"Trọng yếu","NHO":"Nhỏ"}
function MERGE(id, list, key) { const p = ANALYSIS[id]; const a = (list || []).slice(); if (p && p[key]) p[key].forEach(x => { if (a.indexOf(x) < 0) a.push(x) }); return a }
